const _FD=[""];
// atob() decodes base64 to a byte-per-char Latin1 string. Since our data was
// base64-encoded from UTF-8 (accented PT-BR text), we must re-decode those raw
// bytes as UTF-8, or accented characters render as mojibake (e.g. "Ã§Ã£o" instead of "ção").
function b64ToUtf8(b64){
  const binary=atob(b64);
  const bytes=new Uint8Array(binary.length);
  for(let i=0;i<binary.length;i++) bytes[i]=binary.charCodeAt(i);
  return new TextDecoder('utf-8').decode(bytes);
}
// Parse seed data — used ONLY once, to migrate historical data into Supabase
// the very first time a user logs in (see loadAllUserData below).
const _MIGRATION_SEED_SESSIONS=JSON.parse(b64ToUtf8(_FD.join('')));

