function sessionToRow(s,userId){
  return{id:s.id,user_id:userId,date:s.date,name:s.name,duration:s.duration,total_vol:s.totalVol,total_sets:s.totalSets,avg_rpe:s.avgRpe==null?null:Number(s.avgRpe),prs:s.prs||0,calories:s.calories??null,time:s.time??null,exercises:s.exercises};
}
function rowToSession(r){
  return{id:r.id,date:r.date,name:r.name,duration:r.duration,exercises:r.exercises||[],totalVol:r.total_vol,totalSets:r.total_sets,avgRpe:r.avg_rpe,prs:r.prs||0,calories:r.calories,time:r.time};
}
function measureRowToEntry(r){return{date:r.date,...(r.data||{})};}

// ─── PERSISTENCE (Supabase-backed) ──────────────────────────
function loadSavedSessions(){return _sessionsCache;}
function getAllSessions(){return [..._sessionsCache].sort((a,b)=>b.date.localeCompare(a.date));}
async function saveSession(session){
  if(_sessionsCache.find(s=>s.id===session.id))return;
  _sessionsCache=[session,..._sessionsCache];
  refreshDerivedData();
  try{
    const{data:userData}=await supabase.auth.getUser();
    const uid=userData?.user?.id;
    if(!uid)return;
    const{error}=await supabase.from('workout_sessions').insert(sessionToRow(session,uid));
    if(error)console.error('saveSession error',error);
  }catch(e){console.error(e);}
}
function buildWeekly(sessions){
  const weekly={};
  sessions.forEach(s=>{
    if(!s.date)return;
    const d=new Date(s.date+'T12:00:00');
    const day=d.getDay();
    const wkStart=new Date(d);wkStart.setDate(d.getDate()-day);
    const wk=wkStart.toISOString().slice(0,10);
    if(!weekly[wk])weekly[wk]={vol:0,dur:0,reps:0,sets:0,sessions:0};
    weekly[wk].vol+=s.totalVol||0;
    weekly[wk].dur+=s.duration||0;
    weekly[wk].sets+=s.totalSets||0;
    weekly[wk].sessions++;
    s.exercises?.forEach(e=>e.setData?.forEach(st=>{weekly[wk].reps+=(st.r||0);}));
  });
  Object.keys(weekly).forEach(k=>{
    weekly[k].vol=Math.round((weekly[k].vol||0)*100)/100;
    weekly[k].label=new Date(k+'T12:00:00').toLocaleDateString('pt-BR',{day:'2-digit',month:'2-digit'});
  });
  return weekly;
}
function buildExerciseHistory(sessions){
  const hist={};
  const asc=[...sessions].sort((a,b)=>a.date.localeCompare(b.date));
  asc.forEach(s=>{
    s.exercises?.forEach(e=>{
      if(!hist[e.name])hist[e.name]=[];
      hist[e.name].push({d:s.date,sets:e.setData||[]});
    });
  });
  Object.keys(hist).forEach(k=>hist[k].sort((a,b)=>b.d.localeCompare(a.d)));
  return hist;
}
function refreshDerivedData(){
  FEED=getAllSessions();
  WEEKLY=buildWeekly(FEED);
  WEEKS=Object.keys(WEEKLY).sort();
  HIST=buildExerciseHistory(FEED);
  W_DATA=_measureHistoryCache.filter(h=>h["Peso"]!=null).slice().sort((a,b)=>a.date.localeCompare(b.date)).map(h=>parseFloat(h["Peso"]));
}

async function upsertMeasurementRow(uid,date,newFields){
  try{
    const{data:existing}=await supabase.from('measurements').select('id,data').eq('user_id',uid).eq('date',date).maybeSingle();
    const merged={...(existing?.data||{}),...newFields};
    if(existing){await supabase.from('measurements').update({data:merged}).eq('id',existing.id);}
    else{await supabase.from('measurements').insert({user_id:uid,date,data:merged});}
  }catch(e){console.error('upsertMeasurementRow error',e);}
}

function loadBodyMeasures(){
  for(let i=_measureHistoryCache.length-1;i>=0;i--){
    const h=_measureHistoryCache[i];
    if(Object.keys(h).some(k=>k!=="date"&&k!=="Peso"))return h;
  }
  return {};
}
function loadMeasureHistory(){return _measureHistoryCache;}
function saveBodyMeasures(){ /* no-op: persistence happens via saveMeasureHistory below */ }
async function saveMeasureHistory(h){
  _measureHistoryCache=h;
  refreshDerivedData();
  const newest=h[h.length-1];
  if(!newest)return;
  const{data:userData}=await supabase.auth.getUser();
  const uid=userData?.user?.id;
  if(!uid)return;
  const{date,...fields}=newest;
  await upsertMeasurementRow(uid,date,fields);
}

