// ─── ROUTINES (Supabase-backed) ──────────────────────────────
let _routinesCache=[];
function loadRoutines(){return _routinesCache;}
async function fetchRoutines(){
  const{data:userData}=await supabase.auth.getUser();
  const uid=userData?.user?.id;
  if(!uid)return;
  const{data,error}=await supabase.from('routines').select('*').eq('user_id',uid).order('created_at');
  if(!error)_routinesCache=(data||[]).map(r=>({...r,exercises:r.exercises||[]}));
}
async function saveRoutine(routine){
  const{data:userData}=await supabase.auth.getUser();
  const uid=userData?.user?.id;
  if(!uid)return null;
  const row={user_id:uid,name:routine.name,label:routine.label,color:routine.color||'#3B82F6',exercises:routine.exercises,updated_at:new Date().toISOString()};
  if(routine.id){
    await supabase.from('routines').update(row).eq('id',routine.id);
    _routinesCache=_routinesCache.map(r=>r.id===routine.id?{...r,...row}:r);
    return routine.id;
  } else {
    const{data,error}=await supabase.from('routines').insert({...row}).select().single();
    if(!error&&data){_routinesCache=[..._routinesCache,data];return data.id;}
  }
  return null;
}
async function deleteRoutine(id){
  await supabase.from('routines').delete().eq('id',id);
  _routinesCache=_routinesCache.filter(r=>r.id!==id);
}


async function loadAllUserData(){
  const{data:userData}=await supabase.auth.getUser();
  const uid=userData?.user?.id;
  if(!uid)return;

  let[sessRes,measRes,settRes]=await Promise.all([
    supabase.from('workout_sessions').select('*'),
    supabase.from('measurements').select('*'),
    supabase.from('user_settings').select('*').eq('user_id',uid).maybeSingle(),
  ]);

  // First login ever (no rows yet) → seed Supabase once from the historical
  // data that used to be baked into the app bundle.
  if(!sessRes.error&&(sessRes.data||[]).length===0&&_MIGRATION_SEED_SESSIONS.length>0){
    const sessionRows=_MIGRATION_SEED_SESSIONS.map(s=>sessionToRow(s,uid));
    await supabase.from('workout_sessions').insert(sessionRows);
    const measureRows=[...SEED_WEIGHT_HISTORY,...SEED_MEASURE_HISTORY].map(({date,...fields})=>({user_id:uid,date,data:fields}));
    if(measureRows.length)await supabase.from('measurements').insert(measureRows);
    await supabase.from('user_settings').upsert({user_id:uid,weight_goal:74,updated_at:new Date().toISOString()});
    [sessRes,measRes,settRes]=await Promise.all([
      supabase.from('workout_sessions').select('*'),
      supabase.from('measurements').select('*'),
      supabase.from('user_settings').select('*').eq('user_id',uid).maybeSingle(),
    ]);
  }

  _sessionsCache=(sessRes.data||[]).map(rowToSession);
  _measureHistoryCache=(measRes.data||[]).map(measureRowToEntry).sort((a,b)=>a.date.localeCompare(b.date));
  _weightGoalCache=settRes.data?.weight_goal??74;
  refreshDerivedData();
  await fetchRoutines();
}

// ─── SHARED UTILS ────────────────────────────────────────────
function fmt(s){const m=Math.floor(s/60),sec=s%60;return m+":"+(sec<10?"0":"")+sec;}
function orm(w,r){return r>1?Math.round(w*(1+r/30)*10)/10:w;}
function fmtDate(d){const dt=new Date(d+"T12:00:00");const today=new Date();today.setHours(0,0,0,0);const diff=Math.round((today-dt)/86400000);if(diff===0)return"Hoje";if(diff===1)return"Ontem";if(diff<7)return"há "+diff+" dias";return dt.toLocaleDateString("pt-BR",{day:"2-digit",month:"short"});}
function cleanName(n=""){return(n||"").replace(/â[^\s]*/g,"—").replace(/\s+—\s+/g," — ").trim()||"Treino";}
function fmtDur(m){if(!m)return"—";return m>=60?Math.round(m/60)+"h"+(m%60>0?" "+m%60+"min":""):m+"min";}
function getHistory(exName){return(HIST[exName]||[]).slice(-3).reverse();}
function getBestORM(exName){const h=HIST[exName]||[];let best=0;h.forEach(s=>s.sets.forEach(ss=>{if(ss.w>0&&ss.r>0){const v=orm(ss.w,ss.r);if(v>best)best=v;}}));return best;}
function getBestW(exName){return(HIST[exName]||[]).flatMap(s=>s.sets).filter(s=>s.w>0).reduce((a,s)=>Math.max(a,s.w),0);}
function getGreeting(){const h=new Date().getHours();if(h<12)return"Bom dia";if(h<18)return"Boa tarde";return"Boa noite";}

