// ─── SHARED COMPONENTS ───────────────────────────────────────
function Ring({pct,size=56,stroke=5,color,children}){
  const r=(size-stroke*2)/2,circ=2*Math.PI*r,dash=circ*(pct/100);
  return(<div style={{position:"relative",width:size,height:size,flexShrink:0}}>
    <svg width={size} height={size} style={{transform:"rotate(-90deg)"}}>
      <circle cx={size/2} cy={size/2} r={r} fill="none" stroke={C.border} strokeWidth={stroke}/>
      <circle cx={size/2} cy={size/2} r={r} fill="none" stroke={color} strokeWidth={stroke} strokeDasharray={`${dash} ${circ}`} strokeLinecap="round"/>
    </svg>
    <div style={{position:"absolute",inset:0,display:"flex",alignItems:"center",justifyContent:"center"}}>{children}</div>
  </div>);
}

function Sparkline({data,color,height=40}){
  if(!data||data.length<2)return null;
  const mn=Math.min(...data),mx=Math.max(...data),rng=mx-mn||1,w=120,h=height;
  const pts=data.map((v,i)=>[(i/(data.length-1))*w,h-((v-mn)/rng)*(h-6)-3]);
  const path=pts.map((p,i)=>`${i===0?"M":"L"}${p[0].toFixed(1)},${p[1].toFixed(1)}`).join(" ");
  const area=`${path} L${w},${h} L0,${h} Z`;
  return(<svg width={w} height={h} style={{display:"block"}}>
    <defs><linearGradient id="sg" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor={color} stopOpacity="0.3"/><stop offset="100%" stopColor={color} stopOpacity="0"/></linearGradient></defs>
    <path d={area} fill="url(#sg)"/>
    <path d={path} fill="none" stroke={color} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
    <circle cx={pts[pts.length-1][0]} cy={pts[pts.length-1][1]} r="3" fill={color}/>
  </svg>);
}

function LineChart({data,color,height,showAllPoints,unit,onSelect}){
  if(!data||data.length<2)return null;
  const[selIdx,setSelIdx]=useState(data.length-1);
  const h=height||120,vals=data.map(d=>d.y),mn=Math.min(...vals),mx=Math.max(...vals),rng=mx-mn||1,w=300;
  const topPad=showAllPoints?28:8;
  const pts=data.map((d,i)=>({x:(i/(data.length-1))*w,y:h-((d.y-mn)/rng)*(h-16-topPad)-8}));
  const path=pts.map((p,i)=>(i===0?"M":"L")+p.x.toFixed(1)+","+p.y.toFixed(1)).join(" ");
  const area=path+" L"+w+","+h+" L0,"+h+" Z";
  const last=pts[pts.length-1];
  const cid="lg"+color.replace("#","");
  const sel=Math.min(selIdx,data.length-1);
  const selPt=pts[sel];
  if(!showAllPoints){
    return(<svg width="100%" height={h} viewBox={"0 0 "+w+" "+h} preserveAspectRatio="none" style={{overflow:"visible"}}>
      <defs><linearGradient id={cid} x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor={color} stopOpacity="0.3"/><stop offset="100%" stopColor={color} stopOpacity="0"/></linearGradient></defs>
      <path d={area} fill={"url(#"+cid+")"}/>
      <path d={path} fill="none" stroke={color} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
      <circle cx={last.x} cy={last.y} r="4" fill={color} stroke="#07090F" strokeWidth="2"/>
    </svg>);
  }
  function handlePick(i){setSelIdx(i);onSelect&&onSelect(data[i]);}
  return(
    <div>
      <div style={{display:"flex",alignItems:"baseline",gap:6,marginBottom:6}}>
        <span style={{fontSize:20,fontWeight:900,color:C.text}}>{data[sel].y}{unit||""}</span>
        <span style={{fontSize:12,fontWeight:700,color}}>{fmtDate(data[sel].x)}</span>
      </div>
      <svg width="100%" height={h} viewBox={"0 0 "+w+" "+h} preserveAspectRatio="none" style={{overflow:"visible"}}>
        <defs><linearGradient id={cid} x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor={color} stopOpacity="0.3"/><stop offset="100%" stopColor={color} stopOpacity="0"/></linearGradient></defs>
        <path d={area} fill={"url(#"+cid+")"}/>
        <path d={path} fill="none" stroke={color} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
        {pts.map((p,i)=>(
          <circle key={i} cx={p.x} cy={p.y} r={i===sel?5:3} fill={i===sel?color:"#0A0F1E"} stroke={color} strokeWidth={i===sel?2:1.5} onClick={()=>handlePick(i)} style={{cursor:"pointer"}}/>
        ))}
        {selPt&&<line x1={selPt.x} y1={selPt.y} x2={selPt.x} y2={h} stroke={color} strokeWidth="1" strokeDasharray="2,2" opacity="0.4"/>}
      </svg>
      <div style={{position:"relative",height:18,marginTop:2}}>
        {pts.map((p,i)=>(
          <div key={i} onClick={()=>handlePick(i)} style={{position:"absolute",left:(p.x/w*100)+"%",transform:"translateX(-50%)",width:24,height:18,cursor:"pointer"}}/>
        ))}
      </div>
    </div>
  );
}

// ─── WORKOUT DETAIL (shared by Home + Histórico) ─────────────
