// EXERCÍCIOS BROWSER — search all exercises outside a workout
// ══════════════════════════════════════════════════════════════
function ExerciciosBrowserScreen({onNavigate}){
  const[search,setSearch]=useState("");
  const[selGroup,setSelGroup]=useState("Todos");
  const groups=["Todos",...Object.keys(ALL_EXERCISES)];
  const allFlat=Object.entries(ALL_EXERCISES).flatMap(([g,exs])=>exs.map(e=>({name:e,group:g})));
  const filtered=allFlat.filter(e=>{
    const matchGroup=selGroup==="Todos"||(e.group===selGroup);
    const matchSearch=!search||e.name.toLowerCase().includes(search.toLowerCase());
    return matchGroup&&matchSearch;
  });
  return(
    <div style={{background:"#080A0E",minHeight:"100vh",paddingBottom:100}}>
      <div style={{position:"sticky",top:52,zIndex:10,background:"rgba(6,8,12,0.96)",backdropFilter:"blur(20px)",padding:"14px 16px 14px"}}>
        <div style={{display:"flex",alignItems:"center",gap:12,marginBottom:12}}>
          <button onClick={()=>onNavigate("home")} style={{width:36,height:36,borderRadius:"50%",background:C.card,border:"1px solid "+C.border,color:C.sub,fontSize:22,cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>‹</button>
          <div style={{fontSize:18,fontWeight:900,color:C.text,letterSpacing:"-0.5px"}}>Exercícios</div>
        </div>
        <div style={{background:C.card,border:"1px solid "+C.border,borderRadius:12,padding:"10px 14px",display:"flex",alignItems:"center",gap:8}}>
          <span style={{color:C.muted,fontSize:14}}>🔍</span>
          <input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Buscar exercício..." style={{flex:1,background:"none",border:"none",color:C.text,fontSize:16,outline:"none"}}/>
          {search&&<button onClick={()=>setSearch("")} style={{background:"none",border:"none",color:C.muted,fontSize:16,cursor:"pointer",padding:0}}>✕</button>}
        </div>
      </div>
      <div style={{padding:"12px 16px 0"}}>
        <div style={{display:"flex",gap:6,overflowX:"auto",marginBottom:16,paddingBottom:2}}>
          {groups.map(g=>(
            <button key={g} onClick={()=>setSelGroup(g)} style={{flexShrink:0,padding:"6px 14px",borderRadius:99,cursor:"pointer",fontSize:11,fontWeight:700,background:selGroup===g?(GC[g]||C.blueL)+"33":C.card,border:"1px solid "+(selGroup===g?(GC[g]||C.blueL)+"66":C.border),color:selGroup===g?(GC[g]||C.blueXL):C.sub}}>{g}</button>
          ))}
        </div>
        <div style={{fontSize:11,color:C.muted,marginBottom:10}}>{filtered.length} exercício{filtered.length!==1?"s":""}</div>
        {filtered.map(e=>{
          const gc=GC[e.group]||C.blueL;
          const info=EXERCISES_INFO[e.name];
          return(
            <button key={e.name} onClick={()=>onNavigate("exercicio",{name:e.name})} style={{width:"100%",background:C.card,border:"1px solid "+C.border,borderRadius:14,padding:"14px 16px",marginBottom:8,cursor:"pointer",textAlign:"left",display:"flex",alignItems:"center",gap:12}}>
              <div style={{width:40,height:40,borderRadius:10,background:gc+"22",border:"1px solid "+gc+"44",display:"flex",alignItems:"center",justifyContent:"center",fontSize:12,fontWeight:800,color:gc,flexShrink:0}}>{e.name.slice(0,3).toUpperCase()}</div>
              <div style={{flex:1,minWidth:0}}>
                <div style={{fontSize:13,fontWeight:700,color:C.text,marginBottom:2,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{e.name}</div>
                <div style={{display:"flex",gap:8,alignItems:"center"}}>
                  <span style={{fontSize:10,fontWeight:700,color:gc}}>{e.group}</span>
                  {info&&<span style={{fontSize:10,color:C.muted}}>{info.type}</span>}
                </div>
              </div>
              <span style={{color:C.muted,fontSize:16,flexShrink:0}}>›</span>
            </button>
          );
        })}
        {filtered.length===0&&(
          <div style={{textAlign:"center",padding:"40px 20px",color:C.muted}}>
            <div style={{fontSize:32,marginBottom:12}}>🏋️</div>
            <div style={{fontSize:14,fontWeight:600}}>Nenhum exercício encontrado</div>
            <div style={{fontSize:12,marginTop:4}}>Tente outra busca</div>
          </div>
        )}
      </div>
      <BottomNav active="treino" onNavigate={onNavigate}/>
    </div>
  );
}

