// HOME SCREEN
// ══════════════════════════════════════════════════════════════
function HomeScreen({onNavigate,onStartWorkout}){
  const[detail,setDetail]=useState(null);
  const[chartMode,setChartMode]=useState("vol");
  const[chartRange,setChartRange]=useState("3m");
  const[weightPeriod,setWeightPeriod]=useState("1M");

  const chartModes=[{k:"vol",l:"Volume",unit:"t",color:C.blueXL},{k:"dur",l:"Duração",unit:"min",color:C.mint},{k:"reps",l:"Repetições",unit:"",color:C.amber},{k:"sets",l:"Séries",unit:"",color:C.coral}];
  const activeMode=chartModes.find(m=>m.k===chartMode)||chartModes[0];
  const nWeeks={all:WEEKS.length,"3m":13,"1m":4,"1s":1}[chartRange]||13;
  const chartData=WEEKS.slice(-nWeeks).map(wk=>{
    const d=WEEKLY[wk];const dt=new Date(wk+"T12:00:00");
    return{label:dt.toLocaleDateString("pt-BR",{day:"2-digit",month:"short"}),y:d[chartMode]||0};
  });
  const maxY=Math.max(...chartData.map(d=>d.y))||1;
  const lastW=WEEKLY[WEEKS[WEEKS.length-1]]||{};
  const prevW=WEEKLY[WEEKS[WEEKS.length-2]]||{};
  const curr=lastW[chartMode]||0;const prev=prevW[chartMode]||1;
  const delta=Math.round((curr-prev)/prev*100);

  const wPeriods=[{k:"1S",l:"1 sem",n:7},{k:"15D",l:"15 dias",n:15},{k:"1M",l:"30 dias",n:30},{k:"3M",l:"3 meses",n:90},{k:"TUDO",l:"Tudo",n:999}];
  const wpConf=wPeriods.find(p=>p.k===weightPeriod)||wPeriods[2];
  const wSlice=W_DATA.slice(-Math.min(wpConf.n,W_DATA.length));
  const wEnd=wSlice[wSlice.length-1];
  const wStart=wSlice[0]||wEnd;
  const wDelta=+(wEnd-wStart).toFixed(1);
  const wDeltaColor=wDelta<0?C.mint:wDelta>0?C.coral:C.sub;

  const {count:weekWorkouts,vol:weekVolDyn}=getWeekStats();
  const weekProgress=Math.min(weekWorkouts/USER.weekGoal,1);

  if(detail) return <WorkoutDetail session={detail} onClose={()=>setDetail(null)}/>;

  return(
    <div style={{background:"#080A0E",minHeight:"100dvh",paddingTop:52}}>

      {/* ── Greeting ── */}
      <div style={{padding:"14px 20px 0"}}>
        <div style={{fontSize:11,fontWeight:600,color:C.sub,letterSpacing:"0.12em",textTransform:"uppercase",marginBottom:2}}>{getGreeting()},</div>
        <div style={{fontSize:34,fontWeight:900,color:C.text,letterSpacing:"-1.5px",lineHeight:1}}>{USER.name}<span style={{color:C.blueXL}}>.</span></div>
      </div>

      <div style={{padding:"14px 16px 120px"}}>

        {/* ── Next Session card ── */}
        <div style={{background:C.card,border:"1px solid "+C.border,borderRadius:20,overflow:"hidden",marginBottom:10}}>
          <div style={{padding:"14px 20px 12px",borderBottom:"1px solid "+C.border}}>
            <div style={{fontSize:9,fontWeight:700,color:C.blueXL,letterSpacing:"0.16em",textTransform:"uppercase",marginBottom:8}}>Next Session</div>
            <div style={{fontSize:20,fontWeight:800,color:C.text,letterSpacing:"-0.5px",marginBottom:4,textTransform:"uppercase"}}>{USER.nextWorkout.name} — {USER.nextWorkout.label}</div>
            <div style={{fontSize:11,color:C.sub}}>Estimated duration: {Math.round(USER.nextWorkout.exercises.length*10)} min</div>
          </div>
          <div style={{padding:"12px 20px 16px"}}>
            <div style={{display:"flex",gap:5,flexWrap:"wrap",marginBottom:14}}>
              {USER.nextWorkout.exercises.map(ex=><span key={ex} style={{padding:"3px 10px",borderRadius:99,background:C.blueL+"15",border:"1px solid "+C.blueL+"30",color:C.blueXL,fontSize:11,fontWeight:600}}>{ex}</span>)}
            </div>
            <button onClick={()=>{
              const nextPlan=PLANS.find(p=>p.id===USER.nextWorkout.id)||PLANS[0];
              const exs=buildSets(nextPlan);
              onStartWorkout(nextPlan,exs);
              onNavigate("treino");
            }} style={{width:"100%",padding:"13px",background:C.grad,border:"none",borderRadius:13,color:"#fff",fontSize:14,fontWeight:700,cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center",gap:8}}>
              <svg width="14" height="14" fill="#fff" viewBox="0 0 24 24"><path d="M8 5v14l11-7z"/></svg>
              Iniciar Treino
            </button>
          </div>
        </div>

        {/* ── Stats 2×2 grid ── */}
        <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:6,marginBottom:10}}>
          {/* Esta semana */}
          <div style={{background:C.card,border:"1px solid "+C.border,borderRadius:18,padding:"10px 14px"}}>
            <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:8}}>
              <svg width="14" height="14" fill="none" stroke={C.blueXL} strokeWidth="1.8" viewBox="0 0 24 24"><rect x="3" y="4" width="18" height="18" rx="2"/><line x1="16" y1="2" x2="16" y2="6"/><line x1="8" y1="2" x2="8" y2="6"/><line x1="3" y1="10" x2="21" y2="10"/></svg>
            </div>
            <div style={{fontSize:24,fontWeight:900,color:C.text,letterSpacing:"-1px",lineHeight:1}}>{weekWorkouts}<span style={{fontSize:14,color:C.sub,fontWeight:600}}>/{USER.weekGoal}</span></div>
            <div style={{fontSize:9,fontWeight:700,color:C.sub,letterSpacing:"0.1em",textTransform:"uppercase",marginTop:3,marginBottom:6}}>Esta Semana</div>
            <div style={{background:C.border,borderRadius:99,height:2.5,overflow:"hidden"}}>
              <div style={{width:(weekProgress*100)+"%",height:"100%",background:C.blueXL,borderRadius:99,transition:"width 0.6s ease"}}/>
            </div>
          </div>

          {/* Volume */}
          <div style={{background:C.card,border:"1px solid "+C.border,borderRadius:18,padding:"10px 14px"}}>
            <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:8}}>
              <svg width="14" height="14" fill="none" stroke={C.blueXL} strokeWidth="1.8" viewBox="0 0 24 24"><polyline points="22 7 13.5 15.5 8.5 10.5 2 17"/><polyline points="16 7 22 7 22 13"/></svg>
              {delta!==0&&<span style={{fontSize:9,fontWeight:700,color:delta>0?C.mint:C.coral,background:(delta>0?C.mint:C.coral)+"18",padding:"2px 6px",borderRadius:99}}>{delta>0?"+":""}{delta}%</span>}
            </div>
            <div style={{fontSize:24,fontWeight:900,color:C.text,letterSpacing:"-1px",lineHeight:1}}>{curr}<span style={{fontSize:12,color:C.sub,fontWeight:500,marginLeft:2}}>t</span></div>
            <div style={{fontSize:9,fontWeight:700,color:C.sub,letterSpacing:"0.1em",textTransform:"uppercase",marginTop:3}}>Volume</div>
          </div>

          {/* Streak */}
          <div style={{background:C.card,border:"1px solid "+C.border,borderRadius:18,padding:"10px 14px"}}>
            <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:8}}>
              <svg width="14" height="14" fill="none" stroke={C.amber} strokeWidth="1.8" viewBox="0 0 24 24"><polyline points="22 12 18 12 15 21 9 3 6 12 2 12"/></svg>
            </div>
            <div style={{fontSize:24,fontWeight:900,color:C.text,letterSpacing:"-1px",lineHeight:1}}>{USER.streak}</div>
            <div style={{fontSize:9,fontWeight:700,color:C.sub,letterSpacing:"0.1em",textTransform:"uppercase",marginTop:3}}>Streak</div>
          </div>

          {/* Peso corporal */}
          <button onClick={()=>onNavigate("corpo")} style={{background:C.card,border:"1px solid "+C.border,borderRadius:18,padding:"10px 14px",cursor:"pointer",textAlign:"left"}}>
            <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:8}}>
              <svg width="14" height="14" fill="none" stroke={C.blueXL} strokeWidth="1.8" viewBox="0 0 24 24"><circle cx="12" cy="8" r="5"/><path d="M3 21v-1a9 9 0 0 1 18 0v1"/></svg>
              {wDelta!==0&&<span style={{fontSize:9,fontWeight:700,color:wDeltaColor,background:wDeltaColor+"18",padding:"2px 6px",borderRadius:99}}>{wDelta>0?"+":""}{wDelta}kg</span>}
            </div>
            <div style={{fontSize:20,fontWeight:900,color:C.text,letterSpacing:"-0.5px",lineHeight:1,marginBottom:4}}>{wEnd}<span style={{fontSize:12,color:C.sub,fontWeight:500,marginLeft:2}}>kg</span></div>
            <Sparkline data={wSlice} color={wDelta<=0?C.mint:C.coral} height={22}/>
            <div style={{fontSize:9,fontWeight:700,color:C.sub,letterSpacing:"0.1em",textTransform:"uppercase",marginTop:4}}>Bodyweight</div>
          </button>
        </div>

        {/* ── Weekly Volume chart ── */}
        <div style={{background:C.card,border:"1px solid "+C.border,borderRadius:20,padding:"16px 18px 14px",marginBottom:10}}>
          <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:16}}>
            <div style={{fontSize:9,fontWeight:700,color:C.sub,letterSpacing:"0.12em",textTransform:"uppercase"}}>Weekly Volume (ton)</div>
            <div style={{display:"flex",gap:4,alignItems:"center"}}>
              {[{k:"1s",l:"1S"},{k:"1m",l:"1M"},{k:"3m",l:"3M"},{k:"all",l:"All"}].map(r=>(
                <button key={r.k} onClick={()=>setChartRange(r.k)} style={{padding:"3px 8px",borderRadius:6,fontSize:9,fontWeight:700,cursor:"pointer",background:chartRange===r.k?C.blueM:C.surface,border:"1px solid "+(chartRange===r.k?C.blueL:C.border),color:chartRange===r.k?C.text:C.muted}}>{r.l}</button>
              ))}
              <div style={{width:20,height:20,display:"flex",alignItems:"center",justifyContent:"center",marginLeft:4}}>
                <svg width="14" height="14" fill="none" stroke={C.sub} strokeWidth="1.8" viewBox="0 0 24 24"><line x1="18" y1="20" x2="18" y2="10"/><line x1="12" y1="20" x2="12" y2="4"/><line x1="6" y1="20" x2="6" y2="14"/></svg>
              </div>
            </div>
          </div>
          <div style={{height:100,display:"flex",flexDirection:"column"}}>
            <div style={{flex:1,display:"flex",alignItems:"flex-end",gap:3}}>
              {chartData.map((d,i)=>{
                const pct=(d.y||0)/maxY;
                const isLast=i===chartData.length-1;
                return(<div key={i} style={{flex:1,display:"flex",flexDirection:"column",alignItems:"center"}}>
                  <div style={{width:"100%",height:Math.max(pct*80,2),background:isLast?activeMode.color:activeMode.color+"40",borderRadius:"2px 2px 0 0"}}/>
                </div>);
              })}
            </div>
            <div style={{display:"flex",gap:3,marginTop:6}}>
              {chartData.map((d,i)=>{
                const show=chartData.length<=6||i===0||i===chartData.length-1||i===Math.floor(chartData.length/2);
                return(<div key={i} style={{flex:1,textAlign:"center",fontSize:8,color:C.muted}}>{show?d.label:""}</div>);
              })}
            </div>
          </div>
          <div style={{display:"flex",gap:5,marginTop:12,overflowX:"auto"}}>
            {chartModes.map(m=>(
              <button key={m.k} onClick={()=>setChartMode(m.k)} style={{padding:"5px 12px",borderRadius:99,flexShrink:0,cursor:"pointer",background:chartMode===m.k?m.color+"20":C.surface,border:"1px solid "+(chartMode===m.k?m.color+"60":C.border),color:chartMode===m.k?m.color:C.muted,fontSize:11,fontWeight:chartMode===m.k?700:500}}>{m.l}</button>
            ))}
          </div>
        </div>

        {/* ── Painel ── */}
        <div style={{fontSize:9,fontWeight:700,color:C.sub,marginBottom:10,textTransform:"uppercase",letterSpacing:"0.12em"}}>Acesso Rápido</div>
        <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:8,marginBottom:12}}>
          {[
            {dest:"progresso",icon:<svg width="16" height="16" fill="none" stroke="currentColor" strokeWidth="1.8" viewBox="0 0 24 24"><polyline points="22 7 13.5 15.5 8.5 10.5 2 17"/><polyline points="16 7 22 7 22 13"/></svg>,l:"Análise",desc:"Progresso e gráficos"},
            {dest:"exercicios_browser",icon:<svg width="16" height="16" fill="none" stroke="currentColor" strokeWidth="1.8" viewBox="0 0 24 24"><circle cx="6" cy="12" r="3"/><circle cx="18" cy="12" r="3"/><line x1="9" y1="12" x2="15" y2="12"/></svg>,l:"Exercícios",desc:"Catálogo completo"},
            {dest:"medicoes",icon:<svg width="16" height="16" fill="none" stroke="currentColor" strokeWidth="1.8" viewBox="0 0 24 24"><path d="M21 21H3V3"/><path d="M7 14l4-4 4 4 4-4"/></svg>,l:"Medições",desc:"Atualizar medidas"},
            {dest:"calendario",icon:<svg width="16" height="16" fill="none" stroke="currentColor" strokeWidth="1.8" viewBox="0 0 24 24"><rect x="3" y="4" width="18" height="18" rx="2"/><line x1="16" y1="2" x2="16" y2="6"/><line x1="8" y1="2" x2="8" y2="6"/><line x1="3" y1="10" x2="21" y2="10"/></svg>,l:"Calendário",desc:"Histórico de treinos"},
          ].map(p=>(
            <button key={p.dest} onClick={()=>onNavigate(p.dest)} style={{background:C.card,border:"1px solid "+C.border,borderRadius:16,padding:"14px 16px",cursor:"pointer",textAlign:"left",display:"flex",flexDirection:"column",gap:8}}>
              <span style={{color:C.blueXL}}>{p.icon}</span>
              <div>
                <span style={{fontSize:13,fontWeight:700,color:C.text,display:"block"}}>{p.l}</span>
                <span style={{fontSize:10,color:C.sub,display:"block",marginTop:2}}>{p.desc}</span>
              </div>
            </button>
          ))}
        </div>

        {/* ── PRs ── */}
        <div style={{background:C.card,border:"1px solid "+C.border,borderRadius:20,padding:"18px 18px",marginBottom:12}}>
          <div style={{fontSize:9,fontWeight:700,color:C.sub,marginBottom:14,textTransform:"uppercase",letterSpacing:"0.12em"}}>Personal Records</div>
          {USER.prs.map((pr,i)=>{const gc=GC[pr.group]||C.blueL;return(
            <div key={pr.name} style={{display:"flex",alignItems:"center",gap:12,paddingBottom:i<USER.prs.length-1?12:0,marginBottom:i<USER.prs.length-1?12:0,borderBottom:i<USER.prs.length-1?"1px solid "+C.border:"none"}}>
              <div style={{width:34,height:34,borderRadius:10,background:gc+"18",border:"1px solid "+gc+"35",display:"flex",alignItems:"center",justifyContent:"center",fontSize:10,fontWeight:800,color:gc,flexShrink:0}}>{pr.name.slice(0,3).toUpperCase()}</div>
              <div style={{flex:1}}><div style={{fontSize:13,color:C.text,fontWeight:600}}>{pr.full}</div><div style={{fontSize:10,color:C.sub,marginTop:1}}>{pr.group}</div></div>
              <div style={{textAlign:"right"}}><div style={{fontSize:20,fontWeight:800,color:gc,letterSpacing:"-0.5px"}}>{pr.val}</div><div style={{fontSize:9,color:C.muted,textTransform:"uppercase",letterSpacing:"0.06em"}}>kg</div></div>
            </div>
          );})}
        </div>

        {/* ── Feed ── */}
        <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:12}}>
          <div style={{fontSize:9,fontWeight:700,color:C.sub,textTransform:"uppercase",letterSpacing:"0.12em"}}>Treinos Recentes</div>
          <div style={{fontSize:10,color:C.sub}}>{FEED.length} no total</div>
        </div>
        {FEED.map((session,i)=><FeedCard key={i} session={session} onOpen={setDetail}/>)}
      </div>
      <BottomNav active="home" onNavigate={onNavigate}/>
    </div>
  );
}

// ── Routine Screen — shown when tapping a plan card ──
function RoutineScreen({plan,onClose,onStart,onNavigate,onSaved,onDeleted}){
  const[chartMode,setChartMode]=useState("vol");
  const[chartRange,setChartRange]=useState("3m");
  const[selEx,setSelEx]=useState(null);
  const[showMenu,setShowMenu]=useState(false);
  const[editing,setEditing]=useState(plan.isNew||false);
  const[draft,setDraft]=useState({name:plan.name||"",label:plan.label||"",color:plan.color||"#3B82F6",exercises:plan.exercises||[]});
  const[saving,setSaving]=useState(false);
  const[showDelConfirm,setShowDelConfirm]=useState(false);
  const[showExGallery,setShowExGallery]=useState(false);

  const isNew=plan.isNew||!plan.id;

  const allSessions=useMemo(()=>{
    return loadSavedSessions()
      .filter(s=>s.name&&s.name.toLowerCase().includes((plan.label||"").toLowerCase()))
      .sort((a,b)=>a.date.localeCompare(b.date));
  },[plan]);

  const nPts={all:allSessions.length,"1a":12,"3m":6,"1m":4}[chartRange]||6;
  const sessions=allSessions.slice(-nPts);
  const chartData=sessions.map(s=>({
    label:new Date(s.date+"T12:00:00").toLocaleDateString("pt-BR",{day:"2-digit",month:"short"}),
    y:chartMode==="vol"?(s.totalVol||0):chartMode==="sets"?(s.totalSets||0):(s.duration||0)
  }));
  const maxY=Math.max(...chartData.map(d=>d.y),0.01);
  const minY=Math.min(...chartData.map(d=>d.y),0);
  const lastSession=allSessions[allSessions.length-1];
  const W=400,H=140,PAD=10;
  const px2=(i)=>chartData.length>1?i*(W-PAD*2)/(chartData.length-1)+PAD:W/2;
  const py2=(v)=>H-PAD-((v-minY)/(maxY-minY||1))*(H-PAD*2);

  async function handleSave(){
    if(!draft.label.trim())return;
    setSaving(true);
    await saveRoutine({...plan,...draft,id:plan.id});
    setSaving(false);
    setEditing(false);
    onSaved&&onSaved();
  }

  async function handleDelete(){
    if(plan.id){await deleteRoutine(plan.id);}
    onDeleted&&onDeleted();
  }

  async function handleDuplicate(){
    await saveRoutine({name:draft.name+" (cópia)",label:draft.label+" (cópia)",color:draft.color,exercises:draft.exercises});
    onSaved&&onSaved();
    setShowMenu(false);
  }

  if(selEx) return <ExercicioScreen name={selEx} onBack={()=>setSelEx(null)} onNavigate={onNavigate}/>;

  // EDIT MODE
  if(editing){
    return(
      <div style={{position:"fixed",inset:0,zIndex:700,background:"#080A0E",overflowY:"auto",paddingTop:52}}>
        <div style={{position:"sticky",top:52,zIndex:10,background:"rgba(6,8,12,0.96)",backdropFilter:"blur(20px)",padding:"14px 16px",display:"flex",alignItems:"center",justifyContent:"space-between"}}>
          <button onClick={()=>isNew?onClose():setEditing(false)} style={{width:34,height:34,borderRadius:"50%",background:C.card,border:"1px solid "+C.border,color:C.sub,fontSize:20,cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center"}}>‹</button>
          <div style={{fontSize:15,fontWeight:700,color:C.text}}>{isNew?"Nova Rotina":"Editar Rotina"}</div>
          <button onClick={handleSave} disabled={saving} style={{padding:"7px 14px",borderRadius:99,background:C.blueXL,border:"none",color:"#fff",fontSize:13,fontWeight:700,cursor:"pointer",opacity:saving?0.6:1}}>{saving?"Salvando...":"Salvar"}</button>
        </div>
        <div style={{padding:"20px 16px 120px"}}>
          {/* Name */}
          <div style={{marginBottom:16}}>
            <div style={{fontSize:10,color:C.sub,fontWeight:700,textTransform:"uppercase",letterSpacing:"0.06em",marginBottom:6}}>Nome</div>
            <input value={draft.label} onChange={e=>setDraft(d=>({...d,label:e.target.value}))} placeholder="Ex: Push, Pull, Legs..." style={{width:"100%",boxSizing:"border-box",background:C.card,border:"1px solid "+C.border,borderRadius:12,padding:"12px 16px",fontSize:16,fontWeight:700,color:C.text,outline:"none"}}/>
          </div>
          <div style={{marginBottom:16}}>
            <div style={{fontSize:10,color:C.sub,fontWeight:700,textTransform:"uppercase",letterSpacing:"0.06em",marginBottom:6}}>Identificador (DIA 1, etc.)</div>
            <input value={draft.name} onChange={e=>setDraft(d=>({...d,name:e.target.value}))} placeholder="Ex: DIA 1" style={{width:"100%",boxSizing:"border-box",background:C.card,border:"1px solid "+C.border,borderRadius:12,padding:"12px 16px",fontSize:14,color:C.text,outline:"none"}}/>
          </div>
          {/* Color picker */}
          <div style={{marginBottom:20}}>
            <div style={{fontSize:10,color:C.sub,fontWeight:700,textTransform:"uppercase",letterSpacing:"0.06em",marginBottom:8}}>Cor</div>
            <div style={{display:"flex",gap:8,flexWrap:"wrap"}}>
              {["#3B82F6","#10B981","#F59E0B","#EF4444","#A78BFA","#F472B6","#22D3EE","#FB923C"].map(c=>(
                <button key={c} onClick={()=>setDraft(d=>({...d,color:c}))} style={{width:32,height:32,borderRadius:"50%",background:c,border:draft.color===c?"3px solid #fff":"3px solid transparent",cursor:"pointer"}}/>
              ))}
            </div>
          </div>
          {/* Exercises */}
          <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:10}}>
            <div style={{fontSize:13,fontWeight:700,color:C.text}}>Exercícios</div>
            <button onClick={()=>setShowExGallery(true)} style={{fontSize:12,fontWeight:700,color:C.blueXL,background:"none",border:"none",cursor:"pointer"}}>+ Adicionar</button>
          </div>
          {draft.exercises.map((ex,i)=>(
            <div key={i} style={{background:C.card,border:"1px solid "+C.border,borderRadius:12,padding:"12px 16px",marginBottom:8,display:"flex",alignItems:"center",gap:10}}>
              <div style={{flex:1}}>
                <div style={{fontSize:13,fontWeight:700,color:C.text,marginBottom:4}}>{ex.name}</div>
                <div style={{display:"flex",gap:6,alignItems:"center"}}>
                  <input type="number" value={ex.sets?.length||3} onChange={e=>{const n=parseInt(e.target.value)||1;setDraft(d=>({...d,exercises:d.exercises.map((ee,ii)=>ii!==i?ee:{...ee,sets:Array(n).fill({w:ex.sets?.[0]?.w||0,r:ex.sets?.[0]?.r||8})})}));}} style={{width:44,background:C.surface,border:"1px solid "+C.border,borderRadius:8,padding:"4px 8px",fontSize:12,color:C.text,outline:"none",textAlign:"center"}} min="1" max="10"/>
                  <span style={{fontSize:11,color:C.sub}}>séries</span>
                  <span style={{fontSize:11,color:C.muted}}>·</span>
                  <input type="number" value={ex.sets?.[0]?.r||8} onChange={e=>{const r=parseInt(e.target.value)||1;setDraft(d=>({...d,exercises:d.exercises.map((ee,ii)=>ii!==i?ee:{...ee,sets:(ee.sets||[]).map(s=>({...s,r}))})}))} } style={{width:44,background:C.surface,border:"1px solid "+C.border,borderRadius:8,padding:"4px 8px",fontSize:12,color:C.text,outline:"none",textAlign:"center"}} min="1"/>
                  <span style={{fontSize:11,color:C.sub}}>reps</span>
                  <span style={{fontSize:11,color:C.muted}}>·</span>
                  <input type="number" value={ex.sets?.[0]?.w||0} onChange={e=>{const w=parseFloat(e.target.value)||0;setDraft(d=>({...d,exercises:d.exercises.map((ee,ii)=>ii!==i?ee:{...ee,sets:(ee.sets||[]).map(s=>({...s,w}))})}))} } style={{width:52,background:C.surface,border:"1px solid "+C.border,borderRadius:8,padding:"4px 8px",fontSize:12,color:C.text,outline:"none",textAlign:"center"}} min="0" step="0.5"/>
                  <span style={{fontSize:11,color:C.sub}}>kg</span>
                </div>
              </div>
              <button onClick={()=>setDraft(d=>({...d,exercises:d.exercises.filter((_,ii)=>ii!==i)}))} style={{width:28,height:28,borderRadius:"50%",background:"none",border:"none",color:C.coral,fontSize:18,cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>×</button>
            </div>
          ))}
        </div>
        {showExGallery&&(
          <ExerciseGallery onAdd={(name,group)=>{
            setDraft(d=>({...d,exercises:[...d.exercises,{name,group,rest:90,sets:[{w:0,r:8},{w:0,r:8},{w:0,r:8}]}]}));
            setShowExGallery(false);
          }} onClose={()=>setShowExGallery(false)}/>
        )}
      </div>
    );
  }

  // VIEW MODE
  return(
    <div style={{position:"fixed",inset:0,zIndex:700,background:"#080A0E",overflowY:"auto",paddingTop:52}}>
      {/* Header */}
      <div style={{position:"sticky",top:52,zIndex:10,background:"rgba(6,8,12,0.96)",backdropFilter:"blur(20px)",padding:"14px 16px"}}>
        <div style={{display:"flex",alignItems:"center",justifyContent:"space-between"}}>
          <div style={{display:"flex",alignItems:"center",gap:12}}>
            <button onClick={onClose} style={{width:34,height:34,borderRadius:"50%",background:C.card,border:"1px solid "+C.border,color:C.sub,fontSize:20,cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>‹</button>
            <div style={{fontSize:13,fontWeight:700,color:C.sub,textTransform:"uppercase",letterSpacing:"0.06em"}}>Rotina</div>
          </div>
          <button onClick={()=>setShowMenu(true)} style={{width:34,height:34,borderRadius:"50%",background:C.card,border:"1px solid "+C.border,color:C.sub,fontSize:18,cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center"}}>⋯</button>
        </div>
      </div>

      <div style={{padding:"20px 16px 120px"}}>
        <div style={{fontSize:22,fontWeight:900,color:C.text,letterSpacing:"-0.5px",marginBottom:2}}>{plan.name?plan.name+" — ":""}{(plan.label||"").toUpperCase()}</div>
        <button onClick={onStart} style={{width:"100%",padding:"14px",background:C.grad,border:"none",borderRadius:14,color:"#fff",fontSize:15,fontWeight:800,cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center",gap:8,marginTop:16,marginBottom:20}}>
          <svg width="14" height="14" fill="#fff" viewBox="0 0 24 24"><path d="M8 5v14l11-7z"/></svg>
          Iniciar Rotina
        </button>

        {chartData.length>0&&<div style={{background:C.card,border:"1px solid "+C.border,borderRadius:16,padding:16,marginBottom:20}}>
          <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",marginBottom:8}}>
            <div>
              <div style={{fontSize:22,fontWeight:900,color:C.text,letterSpacing:"-1px"}}>{chartData[chartData.length-1]?.y.toFixed(chartMode==="vol"?1:0)}{chartMode==="vol"?"t":chartMode==="sets"?" séries":" min"}</div>
              {lastSession&&<div style={{fontSize:10,color:C.blueXL,marginTop:2}}>{new Date(lastSession.date+"T12:00:00").toLocaleDateString("pt-BR",{day:"numeric",month:"short"})}</div>}
            </div>
            <div style={{display:"flex",gap:4}}>
              {["1m","3m","1a","all"].map(r=>(
                <button key={r} onClick={()=>setChartRange(r)} style={{padding:"4px 8px",borderRadius:99,fontSize:10,fontWeight:700,cursor:"pointer",background:chartRange===r?C.blueXL:"none",border:"1px solid "+(chartRange===r?C.blueXL:C.border),color:chartRange===r?"#fff":C.sub}}>{r==="all"?"Tudo":r==="1a"?"Ano":r==="3m"?"3M":"1M"}</button>
              ))}
            </div>
          </div>
          <div style={{display:"flex",gap:5,marginBottom:10}}>
            {[{k:"vol",l:"Volume"},{k:"sets",l:"Repetições"},{k:"dur",l:"Duração"}].map(m=>(
              <button key={m.k} onClick={()=>setChartMode(m.k)} style={{padding:"4px 8px",borderRadius:99,fontSize:10,fontWeight:700,cursor:"pointer",background:chartMode===m.k?C.blueXL:"none",border:"1px solid "+(chartMode===m.k?C.blueXL:C.border),color:chartMode===m.k?"#fff":C.sub}}>{m.l}</button>
            ))}
          </div>
          <div style={{position:"relative"}}>
            <div style={{position:"absolute",left:0,top:0,bottom:20,width:36,display:"flex",flexDirection:"column",justifyContent:"space-between",pointerEvents:"none"}}>
              {[maxY,Math.round((maxY+minY)/2),minY].map((v,i)=><span key={i} style={{fontSize:8,color:C.muted,lineHeight:1}}>{chartMode==="vol"?v.toFixed(1)+"t":v}{chartMode==="sets"?" s":chartMode==="dur"?"m":""}</span>)}
            </div>
            <div style={{marginLeft:40}}>
              <svg width="100%" height={H} viewBox={`0 0 ${W} ${H}`} preserveAspectRatio="none" style={{overflow:"visible"}}>
                <defs><linearGradient id="rg2" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor={C.blueXL} stopOpacity="0.3"/><stop offset="100%" stopColor={C.blueXL} stopOpacity="0"/></linearGradient></defs>
                {[0,0.5,1].map((f,i)=><line key={i} x1={PAD} y1={PAD+(H-PAD*2)*f} x2={W-PAD} y2={PAD+(H-PAD*2)*f} stroke={C.border} strokeWidth="1" strokeDasharray="4,4"/>)}
                {chartData.length>1&&<polygon points={[...chartData.map((d,i)=>`${px2(i)},${py2(d.y)}`),`${px2(chartData.length-1)},${H-PAD}`,`${px2(0)},${H-PAD}`].join(" ")} fill="url(#rg2)"/>}
                <polyline points={chartData.map((d,i)=>`${px2(i)},${py2(d.y)}`).join(" ")} fill="none" stroke={C.blueXL} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                {chartData.map((d,i)=>(
                  <g key={i}>
                    <circle cx={px2(i)} cy={py2(d.y)} r="4" fill={C.blueXL} stroke={C.bg} strokeWidth="2"/>
                    <text x={px2(i)} y={py2(d.y)-8} textAnchor="middle" fontSize="9" fill={C.sub}>{chartMode==="vol"?d.y.toFixed(1)+"t":d.y}</text>
                  </g>
                ))}
              </svg>
              <div style={{display:"flex",justifyContent:"space-between",marginTop:2}}>
                <span style={{fontSize:9,color:C.muted}}>{chartData[0]?.label}</span>
                <span style={{fontSize:9,color:C.muted}}>{chartData[chartData.length-1]?.label}</span>
              </div>
            </div>
          </div>
        </div>}

        <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:12}}>
          <div style={{fontSize:13,fontWeight:700,color:C.text}}>Exercícios</div>
          {plan.id&&<button onClick={()=>setEditing(true)} style={{fontSize:12,fontWeight:700,color:C.blueXL,background:"none",border:"none",cursor:"pointer"}}>Editar Rotina</button>}
        </div>

        {(plan.exercises||[]).map((ex,i)=>{
          const gc=GC[ex.group]||C.blueL;
          const restMin=ex.rest>=60?Math.floor(ex.rest/60)+"min"+(ex.rest%60>0?" "+ex.rest%60+"s":""):ex.rest+"s";
          return(
            <div key={i} style={{background:C.card,border:"1px solid "+C.border,borderRadius:14,marginBottom:10,overflow:"hidden"}}>
              <button onClick={()=>setSelEx(ex.name)} style={{width:"100%",padding:"12px 16px",background:"none",border:"none",cursor:"pointer",textAlign:"left",display:"flex",alignItems:"center",gap:12}}>
                <div style={{width:36,height:36,borderRadius:10,background:gc+"18",border:"1px solid "+gc+"33",display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>
                  <div style={{width:8,height:8,borderRadius:"50%",background:gc}}/>
                </div>
                <div style={{flex:1}}><div style={{fontSize:14,fontWeight:700,color:gc,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{ex.name}</div></div>
                <svg width="14" height="14" fill="none" stroke={C.muted} strokeWidth="2" viewBox="0 0 24 24"><polyline points="9 18 15 12 9 6"/></svg>
              </button>
              <div style={{padding:"0 16px 8px",display:"flex",alignItems:"center",gap:6}}>
                <svg width="12" height="12" fill="none" stroke={C.blueXL} strokeWidth="1.8" viewBox="0 0 24 24"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>
                <span style={{fontSize:11,color:C.blueXL}}>Descanso: {restMin}</span>
              </div>
              <div style={{borderTop:"1px solid "+C.border}}>
                <div style={{display:"grid",gridTemplateColumns:"40px 1fr 1fr 1fr",padding:"6px 16px",borderBottom:"1px solid "+C.border}}>
                  {["SÉRIE","KG","REPS",""].map((h,i)=><div key={i} style={{fontSize:9,fontWeight:700,color:C.muted,letterSpacing:"0.06em"}}>{h}</div>)}
                </div>
                {(ex.sets||[]).map((s,si)=>(
                  <div key={si} style={{display:"grid",gridTemplateColumns:"40px 1fr 1fr 1fr",padding:"8px 16px",borderBottom:si<ex.sets.length-1?"1px solid "+C.border+"44":"none",alignItems:"center"}}>
                    <div style={{fontSize:13,fontWeight:700,color:C.sub}}>{si+1}</div>
                    <div style={{fontSize:13,color:C.text,fontWeight:600}}>{s.w>0?s.w:"—"}</div>
                    <div style={{fontSize:13,color:C.text,fontWeight:600}}>{s.r}</div>
                    <div/>
                  </div>
                ))}
              </div>
            </div>
          );
        })}
      </div>

      {/* ⋯ Menu */}
      {showMenu&&(
        <div style={{position:"fixed",inset:0,zIndex:900,background:"rgba(0,0,0,0.6)",backdropFilter:"blur(4px)"}} onClick={()=>setShowMenu(false)}>
          <div onClick={e=>e.stopPropagation()} style={{position:"absolute",bottom:0,left:0,right:0,background:C.card,borderRadius:"20px 20px 0 0",padding:"20px 0 40px"}}>
            <div style={{width:36,height:4,borderRadius:2,background:C.border,margin:"0 auto 20px"}}/>
            {[
              {icon:"⧉",label:"Duplicar Rotina",action:handleDuplicate,color:C.text},
              {icon:"✎",label:"Editar Rotina",action:()=>{setEditing(true);setShowMenu(false);},color:C.text},
              {icon:"×",label:"Deletar Rotina",action:()=>{setShowDelConfirm(true);setShowMenu(false);},color:C.coral},
            ].map(item=>(
              <button key={item.label} onClick={item.action} style={{width:"100%",padding:"18px 24px",background:"none",border:"none",cursor:"pointer",display:"flex",alignItems:"center",gap:16,borderBottom:"1px solid "+C.border}}>
                <span style={{fontSize:18,color:item.color,width:24,textAlign:"center"}}>{item.icon}</span>
                <span style={{fontSize:15,fontWeight:600,color:item.color}}>{item.label}</span>
              </button>
            ))}
          </div>
        </div>
      )}

      {/* Delete confirm */}
      {showDelConfirm&&(
        <div style={{position:"fixed",inset:0,zIndex:900,background:"rgba(0,0,0,0.7)",backdropFilter:"blur(4px)",display:"flex",alignItems:"center",justifyContent:"center",padding:24}}>
          <div style={{background:C.card,border:"1px solid "+C.border,borderRadius:20,padding:24,width:"100%",maxWidth:320}}>
            <div style={{fontSize:17,fontWeight:800,color:C.text,marginBottom:8}}>Deletar rotina?</div>
            <div style={{fontSize:13,color:C.sub,marginBottom:20}}>Esta ação não pode ser desfeita.</div>
            <div style={{display:"flex",gap:10}}>
              <button onClick={()=>setShowDelConfirm(false)} style={{flex:1,padding:"12px",borderRadius:12,background:C.surface,border:"1px solid "+C.border,color:C.sub,fontWeight:700,cursor:"pointer"}}>Cancelar</button>
              <button onClick={handleDelete} style={{flex:1,padding:"12px",borderRadius:12,background:C.coral+"22",border:"1px solid "+C.coral+"55",color:C.coral,fontWeight:700,cursor:"pointer"}}>Deletar</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}


// ══════════════════════════════════════════════════════════════
// TREINO SCREEN (RPEModal + RestTimer + ExerciseHistory + Gallery + PlanSelector + ActiveWorkout + FinishScreen)
// ══════════════════════════════════════════════════════════════
// Top-of-screen banner that flashes briefly when a new PR is hit.
function PRToast({pr}){
  if(!pr)return null;
  return(
    <div style={{position:"fixed",top:64,left:16,right:16,zIndex:500,display:"flex",justifyContent:"center",pointerEvents:"none"}}>
      <div style={{display:"flex",alignItems:"center",gap:10,padding:"10px 16px",borderRadius:99,background:"linear-gradient(135deg,#92400E,#B45309,#F59E0B)",boxShadow:"0 6px 24px rgba(245,158,11,0.45)",animation:"prToastIn 0.35s ease-out"}}>
        <span style={{fontSize:18}}>🏆</span>
        <div>
          <div style={{fontSize:12,fontWeight:900,color:"#fff",letterSpacing:"-0.2px"}}>Novo recorde! {pr.name}</div>
          <div style={{fontSize:10,fontWeight:700,color:"#FEF3C7"}}>{pr.w}kg × {pr.r}</div>
        </div>
      </div>
      <style>{`@keyframes prToastIn{from{transform:translateY(-20px);opacity:0}to{transform:translateY(0);opacity:1}}`}</style>
    </div>
  );
}

// Rest-time picker: "Desativado" then 5s steps up to 2min, then 15s steps up to 5min.
function restTimeOptions(){
  const opts=[null]; // "Desativado"
  for(let s=5;s<=120;s+=5) opts.push(s);
  for(let s=135;s<=300;s+=15) opts.push(s);
  return opts;
}
function fmtRest(s){
  if(s==null) return "Desativado";
  if(s<60) return s+"s";
  const m=Math.floor(s/60),r=s%60;
  return m+"min"+(r>0?" "+r+"s":"");
}
function RestTimePickerModal({initial,onSelect,onClose}){
  const opts=restTimeOptions();
  const[sel,setSel]=useState(initial!=null?initial:null);
  return(
    <div style={{position:"fixed",inset:0,zIndex:400,background:"#07090F66",backdropFilter:"blur(2px) brightness(0.85)",display:"flex",alignItems:"flex-end"}} onClick={onClose}>
      <div onClick={e=>e.stopPropagation()} style={{width:"100%",maxHeight:"70vh",background:"rgba(6,8,12,0.96)",backdropFilter:"blur(24px)",borderTop:"1px solid "+C.borderL,borderRadius:"24px 24px 0 0",padding:"20px 20px 24px",display:"flex",flexDirection:"column"}}>
        <div style={{fontSize:11,fontWeight:700,letterSpacing:"0.1em",textTransform:"uppercase",color:C.sub,marginBottom:14,textAlign:"center"}}>Tempo de Descanso</div>
        <div style={{overflowY:"auto",flex:1,marginBottom:14}}>
          {opts.map((s,i)=>(
            <button key={i} onClick={()=>setSel(s)} style={{display:"block",width:"100%",textAlign:"center",padding:"11px",borderRadius:10,marginBottom:4,cursor:"pointer",background:sel===s?C.blueM+"44":"transparent",border:sel===s?"1px solid "+C.blueL:"1px solid transparent",color:sel===s?C.blueXL:s==null?C.muted:C.text,fontSize:sel===s?16:14,fontWeight:sel===s?800:500}}>{fmtRest(s)}</button>
          ))}
        </div>
        <button onClick={()=>onSelect(sel)} style={{width:"100%",padding:"14px",background:C.grad,border:"none",borderRadius:14,color:"#fff",fontSize:14,fontWeight:700,cursor:"pointer"}}>Feito</button>
      </div>
    </div>
  );
}

function RPEModal({onSelect,onSkip}){
  const opts=[6,6.5,7,7.5,8,8.5,9,9.5,10];
  const[sel,setSel]=useState(null);
  const color=!sel?C.sub:sel<=7?C.mint:sel<=8.5?C.amber:C.coral;
  return(
    <div style={{position:"fixed",inset:0,zIndex:400,background:"#07090F33",backdropFilter:"blur(2px) brightness(0.85)",display:"flex",alignItems:"flex-end"}}>
      <div style={{width:"100%",background:C.surface+"DD",backdropFilter:"blur(24px)",borderTop:"1px solid "+C.borderL,borderRadius:"24px 24px 0 0",padding:"24px 20px 40px"}}>
        <div style={{textAlign:"center",marginBottom:20}}>
          <div style={{fontSize:11,fontWeight:700,letterSpacing:"0.1em",textTransform:"uppercase",color:C.sub,marginBottom:8}}>RPE — Como foi essa série?</div>
          {sel?<div><span style={{fontSize:40,fontWeight:900,color,letterSpacing:"-1px"}}>{sel}</span><span style={{fontSize:14,color:C.sub,marginLeft:8}}>{RPE_LABELS[sel]}</span></div>:<div style={{fontSize:28,fontWeight:900,color:C.muted}}>—</div>}
        </div>
        <div style={{display:"flex",gap:4,marginBottom:20,alignItems:"flex-end",height:64}}>
          {opts.map(v=>{const c=v<=7?C.mint:v<=8.5?C.amber:C.coral;const h=8+(v-6)/4*48;return(<button key={v} onTouchStart={()=>setSel(v)} onClick={()=>setSel(v)} style={{flex:1,height:h,borderRadius:6,cursor:"pointer",border:"none",background:sel===v?c:c+"44",boxShadow:sel===v?"0 0 12px "+c+"88":"none"}}/>);})}
        </div>
        <div style={{display:"flex",gap:4,marginBottom:20}}>
          {opts.map(v=><button key={v} onClick={()=>setSel(v)} style={{flex:1,padding:"6px 2px",borderRadius:8,cursor:"pointer",background:sel===v?(v<=7?C.mint:v<=8.5?C.amber:C.coral)+"33":C.card,border:"1px solid "+(sel===v?(v<=7?C.mint:v<=8.5?C.amber:C.coral):C.border),color:sel===v?(v<=7?C.mint:v<=8.5?C.amber:C.coral):C.sub,fontSize:12,fontWeight:800}}>{v}</button>)}
        </div>
        <div style={{display:"flex",gap:10}}>
          <button onClick={onSkip} style={{flex:1,padding:"14px",background:C.card,border:"1px solid "+C.border,borderRadius:14,color:C.sub,fontSize:14,fontWeight:600,cursor:"pointer"}}>Pular</button>
          <button onClick={()=>sel&&onSelect(sel)} disabled={!sel} style={{flex:2,padding:"14px",background:sel?C.grad:"none",border:sel?"none":"1px solid "+C.border,borderRadius:14,color:sel?"#fff":C.muted,fontSize:14,fontWeight:700,cursor:sel?"pointer":"default"}}>Confirmar RPE {sel||""}</button>
        </div>
      </div>
    </div>
  );
}

function RestTimer({seconds,onDone,onSkip}){
  const[left,setLeft]=useState(seconds);
  const pct=Math.max(0,left/seconds*100);
  const color=left>60?C.mint:left>30?C.amber:C.coral;
  useEffect(()=>{if(left<=0){onDone();return;}const t=setTimeout(()=>setLeft(l=>l-1),1000);return()=>clearTimeout(t);},[left]);
  return(
    <div style={{position:"fixed",bottom:"calc(88px + env(safe-area-inset-bottom, 0px))",left:12,right:12,zIndex:200,background:C.surface+"F8",backdropFilter:"blur(20px)",borderRadius:18,border:"1px solid "+color+"66",overflow:"hidden",boxShadow:"0 4px 32px rgba(0,0,0,0.5)"}}>
      <div style={{height:3,background:C.border,width:"100%"}}><div style={{height:"100%",background:color,width:pct+"%",transition:"width 1s linear"}}/></div>
      <div style={{display:"flex",alignItems:"center",gap:10,padding:"12px 16px 16px"}}>
        <div style={{display:"flex",flexDirection:"column",alignItems:"center",minWidth:52}}>
          <div style={{fontSize:26,fontWeight:900,color,letterSpacing:"-1px",lineHeight:1}}>{fmt(left)}</div>
          <div style={{fontSize:9,fontWeight:700,letterSpacing:"0.1em",textTransform:"uppercase",color:C.sub,marginTop:2}}>descanso</div>
        </div>
        <div style={{display:"flex",gap:6,flex:1,justifyContent:"center"}}>
          {[-30,-15,15,30].map(d=><button key={d} onClick={()=>setLeft(l=>Math.max(0,l+d))} style={{padding:"8px 10px",borderRadius:10,background:d<0?C.coral+"22":C.mint+"22",border:"1px solid "+(d<0?C.coral+"44":C.mint+"44"),color:d<0?C.coral:C.mint,fontSize:11,fontWeight:700,cursor:"pointer"}}>{d>0?"+":""}{d}s</button>)}
        </div>
        <button onClick={onSkip} style={{padding:"10px 16px",borderRadius:12,background:color+"22",border:"1px solid "+color+"55",color,fontSize:13,fontWeight:700,cursor:"pointer"}}>Pular →</button>
      </div>
    </div>
  );
}

function WarmupSection({exWarm,exIdx,updateSet,markDone}){
  const[open,setOpen]=useState(false);
  const doneCnt=exWarm.filter(s=>s.done).length;
  return(
    <div style={{padding:"0 12px 6px"}}>
      <button onClick={()=>setOpen(o=>!o)} style={{width:"100%",background:"none",border:"1px solid rgba(245,158,11,0.2)",borderRadius:10,padding:"7px 12px",display:"flex",alignItems:"center",justifyContent:"space-between",cursor:"pointer",marginBottom:open?8:0}}>
        <span style={{fontSize:9,fontWeight:700,letterSpacing:"0.1em",textTransform:"uppercase",color:C.amber}}>Aquecimento {doneCnt>0?`${doneCnt}/${exWarm.length} ✓`:""}</span>
        <span style={{color:C.muted,fontSize:11,transform:open?"rotate(180deg)":"none",transition:"transform .2s"}}>▾</span>
      </button>
      {open&&exWarm.map((set,wi)=>(
        <div key={wi} style={{display:"flex",alignItems:"center",gap:6,padding:"5px 0",borderBottom:"1px solid rgba(255,255,255,0.04)",opacity:set.done?0.5:1}}>
          <div style={{width:22,height:22,borderRadius:6,background:C.amber+"18",border:"1px solid "+C.amber+"33",display:"flex",alignItems:"center",justifyContent:"center",fontSize:9,fontWeight:800,color:C.amber,flexShrink:0}}>W{wi+1}</div>
          <SmartInput value={set.w} onChange={v=>updateSet(exIdx,wi,"w",v)} readOnly={set.done} unit="kg" color={C.amber}/>
          <span style={{color:C.muted,fontSize:11}}>×</span>
          <SmartInput value={set.r} onChange={v=>updateSet(exIdx,wi,"r",v)} readOnly={set.done} unit="reps" integer color={C.amber}/>
          <button onClick={()=>markDone(wi,exIdx)} style={{width:30,height:30,borderRadius:7,flexShrink:0,background:set.done?C.amber+"22":"rgba(255,255,255,0.03)",border:"1px solid "+(set.done?C.amber+"44":"rgba(255,255,255,0.08)"),color:set.done?C.amber:C.muted,fontSize:14,cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center"}}>{set.done?"✓":"○"}</button>
        </div>
      ))}
    </div>
  );
}

function ExerciseHistory({exName,currentSets}){
  const[open,setOpen]=useState(false);
  const hist=getHistory(exName);
  const bestEver=getBestORM(exName);const bestEverW=getBestW(exName);
  let currentBest=0;
  currentSets.forEach(s=>{if(s.w>0&&s.r>0){const v=orm(s.w,s.r);if(v>currentBest)currentBest=v;}});
  const currentMaxW=currentSets.filter(s=>s.w>0).reduce((a,s)=>Math.max(a,s.w),0);
  const isPR=(currentBest>bestEver&&currentBest>0)||(currentMaxW>bestEverW&&currentMaxW>0);
  const lastSession=hist[0];
  const lastStr=lastSession?`${lastSession.sets[0]?.w}kg × ${lastSession.sets[0]?.r} · ${fmtDate(lastSession.d)}`:"Primeira vez";
  return(
    <div style={{marginBottom:12}}>
      <button onClick={()=>setOpen(o=>!o)} style={{width:"100%",background:C.card,border:"1px solid "+(isPR?C.amber+"55":"rgba(255,255,255,0.06)"),borderRadius:12,padding:"10px 14px",display:"flex",alignItems:"center",justifyContent:"space-between",cursor:"pointer"}}>
        <div style={{display:"flex",alignItems:"center",gap:8}}>
          <span style={{fontSize:9,fontWeight:700,letterSpacing:"0.1em",textTransform:"uppercase",color:isPR?C.amber:C.muted}}>{isPR?"🏆 Novo PR":"Histórico"}</span>
          {!open&&lastSession&&<span style={{fontSize:11,color:C.sub}}>{lastStr}</span>}
        </div>
        <span style={{color:C.muted,fontSize:12,transform:open?"rotate(180deg)":"none",transition:"transform .2s"}}>▾</span>
      </button>
      {open&&(
        <div style={{background:C.card,border:"1px solid "+C.border,borderRadius:"0 0 12px 12px",borderTop:"none",padding:"10px 14px"}}>
          {!hist.length?<div style={{fontSize:11,color:C.muted}}>Primeira vez neste exercício 🎯</div>:
            hist.map((session,i)=>{
              const bestSet=session.sets.reduce((a,b)=>orm(b.w,b.r)>orm(a.w,a.r)?b:a,session.sets[0]);
              const avgRpe=session.sets.filter(s=>s.rpe).length>0?(session.sets.filter(s=>s.rpe).reduce((s,s2)=>s+s2.rpe,0)/session.sets.filter(s=>s.rpe).length).toFixed(1):null;
              const rpeColor=avgRpe?(avgRpe<=7?C.mint:avgRpe<=8.5?C.amber:C.coral):null;
              return(<div key={i} style={{display:"flex",alignItems:"center",gap:10,padding:"7px 0",borderBottom:i<hist.length-1?"1px solid rgba(255,255,255,0.04)":"none"}}>
                <div style={{width:5,height:5,borderRadius:"50%",background:i===0?C.blueXL:C.muted,flexShrink:0}}/>
                <div style={{fontSize:11,color:C.sub,width:56,flexShrink:0}}>{fmtDate(session.d)}</div>
                <div style={{flex:1}}><span style={{fontSize:13,fontWeight:700,color:i===0?C.text:C.sub}}>{bestSet.w}kg × {bestSet.r}</span><span style={{fontSize:11,color:C.muted,marginLeft:6}}>{session.sets.length} s</span></div>
                {avgRpe&&<div style={{fontSize:11,fontWeight:700,color:rpeColor}}>RPE {avgRpe}</div>}
              </div>);
            })
          }
          {bestEver>0&&!isPR&&<div style={{marginTop:8,paddingTop:8,borderTop:"1px solid rgba(255,255,255,0.04)",fontSize:11,color:C.muted}}>Recorde: <span style={{color:C.text,fontWeight:700}}>{bestEver}kg 1RM</span></div>}
        </div>
      )}
    </div>
  );
}

function ExerciseGallery({onAdd,onClose}){
  const[selGroup,setSelGroup]=useState("Peito");
  return(
    <div style={{position:"fixed",inset:0,zIndex:500,background:"#000000EE",backdropFilter:"blur(12px)",display:"flex",flexDirection:"column"}}>
      <div style={{padding:"52px 16px 16px",borderBottom:"1px solid "+C.border,background:C.surface}}>
        <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:14}}>
          <div style={{fontSize:20,fontWeight:800,color:C.text}}>Adicionar exercício</div>
          <button onClick={onClose} style={{width:34,height:34,borderRadius:99,background:C.card,border:"1px solid "+C.border,color:C.sub,fontSize:18,cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center"}}>×</button>
        </div>
        <div style={{display:"flex",gap:6,overflowX:"auto",paddingBottom:2}}>
          {Object.keys(ALL_EXERCISES).map(g=><button key={g} onClick={()=>setSelGroup(g)} style={{padding:"5px 14px",borderRadius:99,flexShrink:0,cursor:"pointer",background:selGroup===g?(GC[g]||C.blueL)+"33":C.card,border:"1px solid "+(selGroup===g?(GC[g]||C.blueL)+"66":C.border),color:selGroup===g?(GC[g]||C.blueL):C.sub,fontSize:12,fontWeight:700}}>{g}</button>)}
        </div>
      </div>
      <div style={{flex:1,overflow:"auto",padding:"12px 16px"}}>
        {(ALL_EXERCISES[selGroup]||[]).map(ex=>{
          const hist=HIST[ex]||[];const lastSess=hist[hist.length-1];const lastStr=lastSess?lastSess.d.slice(5)+" · "+lastSess.sets[0]?.w+"kg":null;
          return(<button key={ex} onClick={()=>onAdd(ex,selGroup)} style={{width:"100%",textAlign:"left",background:C.card,border:"1px solid "+C.border,borderRadius:14,padding:"14px 16px",marginBottom:8,cursor:"pointer",display:"flex",justifyContent:"space-between",alignItems:"center"}}>
            <div><div style={{fontSize:14,fontWeight:700,color:C.text,marginBottom:2}}>{ex}</div><div style={{fontSize:11,color:C.muted}}>{lastStr?"Último: "+lastStr:"Nunca feito"}</div></div>
            <span style={{color:C.blueXL,fontSize:20,fontWeight:300}}>+</span>
          </button>);
        })}
      </div>
    </div>
  );
}

// ─── SMART INPUT — shows previous value dimmed, clears on focus ───
function SmartInput({value,onChange,readOnly,unit,integer,color,compact}){
  const[focused,setFocused]=useState(false);
  const[draft,setDraft]=useState("");
  const display=focused?draft:String(value||"");
  const pad=compact?"1px 3px":"4px";
  return(
    <div style={{background:C.card,border:"1px solid "+C.border,borderRadius:compact?6:8,padding:pad,textAlign:"center",flex:1}}>
      <input
        type="number"
        value={display}
        onFocus={e=>{if(!readOnly){setFocused(true);setDraft("");e.target.select();}}}
        onBlur={()=>{
          if(!readOnly){
            const parsed=integer?parseInt(draft):parseFloat(draft);
            if(!isNaN(parsed)&&parsed>0) onChange(parsed);
            setFocused(false);setDraft("");
          }
        }}
        onChange={e=>!readOnly&&setDraft(e.target.value)}
        readOnly={readOnly}
        style={{width:"100%",background:"none",border:"none",outline:"none",fontSize:compact?14:16,fontWeight:900,color:focused?"#fff":(color||"#fff"),textAlign:"center",WebkitAppearance:"none",opacity:focused?1:(value?1:0.35)}}
        inputMode={integer?"numeric":"decimal"}
      />
      <div style={{fontSize:7,color:"rgba(255,255,255,0.3)",textTransform:"uppercase"}}>{unit}</div>
    </div>
  );
}

function TreinoScreen({onNavigate,activeWorkout,onStartWorkout,onEndWorkout,onUpdateWorkout,onSubScreen,forceActive,onMinimize,onWorkoutSaved}){
  const isActive=!!activeWorkout;
  const plan=activeWorkout?.plan||null;
  const exercises=activeWorkout?.exercises||[];
  const currentEx=activeWorkout?.currentEx||0;
  const elapsed=activeWorkout?.elapsed||0;

  function setExercises(patch){onUpdateWorkout(prev=>({...prev,exercises:typeof patch==="function"?patch(prev.exercises):patch}));}
  function setCurrentEx(v){onUpdateWorkout(prev=>({...prev,currentEx:typeof v==="function"?v(prev.currentEx):v}));}

  function setScreen(s){_setScreen(s);onSubScreen&&onSubScreen(s);}
  const[screen,_setScreen]=useState(isActive?"active":"plans");
  const[restTimer,setRestTimer]=useState(null);
  const[rpeModal,setRpeModal]=useState(null);
  const[finishing,setFinishing]=useState(false);
  const[finishedSession,setFinishedSession]=useState(null);
  const[showGallery,setShowGallery]=useState(false);
  const[showEndConfirm,setShowEndConfirm]=useState(false);
  const[prAnimSi,setPrAnimSi]=useState(null);
  const[prToast,setPrToast]=useState(null);
  const[showExMenu,setShowExMenu]=useState(false);
  const[restPickerEi,setRestPickerEi]=useState(null);
  const[showReorder,setShowReorder]=useState(false);
  const[reorderList,setReorderList]=useState([]);
  const[finishPse,setFinishPse]=useState(null);
  const finishPses=[6,7,7.5,8,8.5,9,9.5];
  const[showRetro,setShowRetro]=useState(false);
  const nowForRetro=new Date();
  const[retroDate,setRetroDate]=useState(nowForRetro.toISOString().slice(0,10));
  const[retroTime,setRetroTime]=useState(String(nowForRetro.getHours()).padStart(2,"0")+":"+String(nowForRetro.getMinutes()).padStart(2,"0"));
  const[retroDurMin,setRetroDurMin]=useState(null);
  const[searchQ,setSearchQ]=useState("");
  const[selectedPlan,setSelectedPlan]=useState(null);
  const[routines,setRoutines]=useState(()=>loadRoutines());
  const[routinesSaved,setRoutinesSaved]=useState(0);

  // Reload routines when saved
  useEffect(()=>{setRoutines(loadRoutines());},[routinesSaved]);
  function refreshRoutines(){fetchRoutines().then(()=>{setRoutines(loadRoutines());setRoutinesSaved(n=>n+1);});}

  // Sync screen state when workout starts/ends externally
  useEffect(()=>{
    if(isActive&&screen==="plans") setScreen("active");
    if(!isActive) setScreen("plans");
  },[isActive]);

  // When parent asks us to go to active (e.g. clicking the mini bar)
  useEffect(()=>{
    if(forceActive&&isActive) setScreen("active");
  },[forceActive]);

  function startPlan(p){
    const exs=buildSets(p);
    onStartWorkout(p,exs);
    setFinishing(false);
    setScreen("active");
  }

  function handleEnd(){
    onEndWorkout();
    setScreen("plans");
    setFinishing(false);
    // finishedSession stays set so detail screen shows
  }

  const ex=exercises[currentEx];
  const totalDone=exercises.reduce((n,e)=>n+e.activeSets.filter(s=>s.done&&s.type==="work").length,0);
  const totalSets=exercises.reduce((n,e)=>n+e.activeSets.filter(s=>s.type==="work").length,0);
  const progress=totalSets>0?totalDone/totalSets:0;

  function updateSet(ei,si,field,val){setExercises(prev=>prev.map((e,i)=>i!==ei?e:{...e,activeSets:e.activeSets.map((s,j)=>j!==si?s:{...s,[field]:val})}));}

  function markDone(si,forceEi){
    const ei=forceEi!==undefined?forceEi:currentEx;
    const exTarget=exercises[ei];const set=exTarget.activeSets[si];
    if(set.done){updateSet(ei,si,"done",false);return;}
    updateSet(ei,si,"done",true);
    const exWarmLen=exTarget.activeSets.filter(s=>s.type==="warmup").length;
    if(set.type==="work"){setTimeout(()=>setRpeModal({ei,si,rest:exTarget.rest}),700);}
    else{setRestTimer({seconds:si===exWarmLen-1?105:60});}
  }

  function handleRpeSelect(rpe){
    if(!rpeModal)return;
    const{ei,si,rest}=rpeModal;
    updateSet(ei,si,"rpe",rpe);
    // Confirming RPE also marks the set as done — covers both flows:
    // tap ✓ first (already done) → RPE opens automatically, or tap RPE directly → this completes it.
    setExercises(prev=>prev.map((e,i)=>i!==ei?e:{...e,activeSets:e.activeSets.map((s,j)=>j!==si?s:{...s,rpe,done:true})}));
    setRpeModal(null);
    const set={...exercises[ei].activeSets[si],rpe,done:true};
    const setORM=set.w>0&&set.r>0?orm(set.w,set.r):0;
    const bestORM=getBestORM(exercises[ei].name);const bestW=getBestW(exercises[ei].name);
    const exWork=exercises[ei].activeSets.filter(s=>s.type==="work");
    const wIdx=exWork.findIndex((_,i)=>exercises[ei].activeSets.indexOf(exWork[i])===si);
    const sessORM=exWork.slice(0,wIdx).filter(s=>s.done&&s.w>0&&s.r>0).reduce((a,s)=>Math.max(a,orm(s.w,s.r)),0);
    const sessW=exWork.slice(0,wIdx).filter(s=>s.done&&s.w>0).reduce((a,s)=>Math.max(a,s.w),0);
    if((setORM>bestORM&&setORM>sessORM&&setORM>0)||(set.w>bestW&&set.w>sessW&&set.w>0)){
      setPrAnimSi({ei,si});setTimeout(()=>setPrAnimSi(null),1200);
      setPrToast({name:exercises[ei].name,w:set.w,r:set.r});setTimeout(()=>setPrToast(null),3200);
    }
    if(rest!=null)setRestTimer({seconds:rest});
  }

  function addExercise(name,group){
    const newEx={name,group,rest:90,warmup:false,activeSets:[{w:0,r:8,done:false,type:"work",rpe:null},{w:0,r:8,done:false,type:"work",rpe:null},{w:0,r:8,done:false,type:"work",rpe:null}]};
    setExercises(prev=>[...prev,newEx]);setCurrentEx(exercises.length);setShowGallery(false);
  }

  // FINISHED SESSION DETAIL — shown after saving (check first, before plans)
  if(finishedSession){
    const s=finishedSession;
    return(
      <div style={{background:"#080A0E",minHeight:"100dvh",padding:"52px 20px 120px"}}>
        <div style={{textAlign:"center",marginBottom:28}}>
          <div style={{fontSize:56,marginBottom:10}}>🏆</div>
          <div style={{fontSize:28,fontWeight:900,color:C.text,letterSpacing:"-1px",marginBottom:4}}>Treino salvo!</div>
          <div style={{fontSize:14,color:C.sub}}>{s.plan} — {s.label}</div>
        </div>
        <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:10,marginBottom:14}}>
          {[{label:"Duração",value:fmt(s.elapsed),color:C.blueXL},{label:"Volume",value:(s.vol/1000).toFixed(1)+"t",color:C.mint},{label:"Séries",value:s.sets,color:C.amber},{label:"RPE Médio",value:s.avgRpe?s.avgRpe+" / 10":"—",color:C.coral}].map(st=>(
            <div key={st.label} style={{background:C.card,backdropFilter:"blur(20px)",border:"1px solid "+C.border,borderRadius:18,padding:"16px",textAlign:"center"}}>
              <div style={{fontSize:9,fontWeight:700,letterSpacing:"0.1em",textTransform:"uppercase",color:C.sub,marginBottom:6}}>{st.label}</div>
              <div style={{fontSize:24,fontWeight:900,color:st.color}}>{st.value}</div>
            </div>
          ))}
        </div>
        {s.pse&&<div style={{background:C.card,border:"1px solid "+C.border,borderRadius:18,padding:"14px 16px",marginBottom:14,display:"flex",alignItems:"center",justifyContent:"space-between"}}>
          <span style={{fontSize:13,color:C.sub}}>Percepção de esforço</span>
          <span style={{fontSize:18,fontWeight:900,color:C.blueXL}}>{s.pse} / 10</span>
        </div>}
        <div style={{background:C.card,border:"1px solid "+C.border,borderRadius:18,padding:"14px 16px",marginBottom:24}}>
          <div style={{fontSize:11,fontWeight:700,color:C.sub,textTransform:"uppercase",letterSpacing:"0.08em",marginBottom:10}}>Exercícios realizados</div>
          {s.exercises.map((ex,i)=>{
            const done=ex.activeSets.filter(st=>st.done&&st.type==="work");
            if(!done.length) return null;
            const vol=done.reduce((a,st)=>a+st.w*st.r,0);
            return(
              <div key={i} style={{display:"flex",alignItems:"center",justifyContent:"space-between",padding:"8px 0",borderBottom:i<s.exercises.length-1?"1px solid rgba(255,255,255,0.05)":"none"}}>
                <div>
                  <div style={{fontSize:13,fontWeight:600,color:C.text}}>{ex.name}</div>
                  <div style={{fontSize:11,color:C.sub}}>{done.length} séries · {vol}kg</div>
                </div>
                <div style={{fontSize:12,color:C.mint,fontWeight:700}}>{done.map(st=>st.w+"×"+st.r).join(", ")}</div>
              </div>
            );
          })}
        </div>
        <div style={{display:"flex",gap:10}}>
          <button onClick={()=>{setFinishedSession(null);onNavigate("progresso");}} style={{flex:1,padding:"16px",background:"rgba(255,255,255,0.06)",border:"1px solid rgba(255,255,255,0.1)",borderRadius:16,color:C.text,fontSize:15,fontWeight:700,cursor:"pointer"}}>Ver Progresso</button>
          <button onClick={()=>{setFinishedSession(null);setScreen("plans");}} style={{flex:1,padding:"16px",background:C.grad,border:"none",borderRadius:16,color:"#fff",fontSize:15,fontWeight:700,cursor:"pointer"}}>Fechar</button>
        </div>
        <BottomNav active="treino" onNavigate={(dest)=>{setFinishedSession(null);onNavigate(dest);}}/>
      </div>
    );
  }

  // PLAN SELECTOR
  if(screen==="plans"){
    const allPlans=routines.length>0?routines:PLANS;
    const filtered=allPlans.filter(p=>{
      if(!searchQ) return true;
      const q=searchQ.toLowerCase();
      return (p.name||"").toLowerCase().includes(q)||(p.label||"").toLowerCase().includes(q)||p.exercises.some(e=>(e.name||"").toLowerCase().includes(q));
    });
    const estimateDur=(p)=>Math.round(p.exercises.reduce((t,e)=>t+(e.sets?.length||3)*(1.5+(e.rest||90)/60),0));
    return(
      <div style={{background:"#080A0E",minHeight:"100dvh",position:"relative",paddingTop:52}}>
        <div style={{padding:"0 20px 8px"}}>
          <div style={{fontSize:26,fontWeight:900,color:"#FFFFFF",letterSpacing:"-1px"}}>
            {isActive?"Treino Ativo":"Meus Treinos"}
          </div>
        </div>

        {/* Search */}
        <div style={{padding:"0 16px",marginBottom:10}}>
          <div style={{background:C.card,border:"1px solid "+C.border,borderRadius:12,padding:"9px 14px",display:"flex",alignItems:"center",gap:10}}>
            <svg width="14" height="14" fill="none" stroke="#3B4560" strokeWidth="2" viewBox="0 0 24 24"><circle cx="11" cy="11" r="8"/><line x1="21" y1="21" x2="16.65" y2="16.65"/></svg>
            <input value={searchQ} onChange={e=>setSearchQ(e.target.value)} placeholder="Buscar treino..." style={{background:"none",border:"none",outline:"none",color:"#6B7FA3",fontSize:13,flex:1,fontFamily:"inherit"}}/>
          </div>
        </div>

        {/* Nova Rotina button */}
        <div style={{padding:"0 16px",marginBottom:10}}>
          <button onClick={()=>setSelectedPlan({isNew:true,name:"",label:"Nova Rotina",color:"#3B82F6",exercises:[]})} style={{width:"100%",padding:"10px 16px",background:C.card,border:"1px solid rgba(255,255,255,0.10)",borderRadius:12,color:C.sub,fontSize:13,fontWeight:600,cursor:"pointer",display:"flex",alignItems:"center",gap:8}}>
            <svg width="14" height="14" fill="none" stroke={C.sub} strokeWidth="2" viewBox="0 0 24 24"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg>
            Nova Rotina
          </button>
        </div>

        <div style={{padding:"0 16px 160px",display:"flex",flexDirection:"column",gap:8}}>
          {/* Active workout banner */}
          {isActive&&(
            <button onClick={()=>setScreen("active")} style={{width:"100%",padding:"14px 18px",background:"linear-gradient(135deg,"+C.blueM+","+C.blueL+")",border:"none",borderRadius:16,cursor:"pointer",textAlign:"left",display:"flex",alignItems:"center",gap:12,marginBottom:4}}>
              <div style={{width:38,height:38,borderRadius:10,flexShrink:0,background:"rgba(255,255,255,0.15)",display:"flex",alignItems:"center",justifyContent:"center"}}>
                <svg width="16" height="16" fill="#fff" viewBox="0 0 24 24"><path d="M8 5v14l11-7z"/></svg>
              </div>
              <div style={{flex:1}}>
                <div style={{fontSize:14,fontWeight:700,color:"#fff",marginBottom:2}}>Continuar treino</div>
                <div style={{fontSize:10,color:"#BFDBFE"}}>{exercises[currentEx]?.name||""} · {exercises.reduce((n,e)=>n+e.activeSets.filter(s=>s.done&&s.type==="work").length,0)}/{exercises.reduce((n,e)=>n+e.activeSets.filter(s=>s.type==="work").length,0)} séries</div>
              </div>
              <svg width="14" height="14" fill="none" stroke="rgba(255,255,255,0.6)" strokeWidth="2" viewBox="0 0 24 24"><polyline points="9 18 15 12 9 6"/></svg>
            </button>
          )}

          {filtered.map((p)=>{
            const dur=estimateDur(p);
            const exPrev=p.exercises.map(e=>e.name).join(", ");
            return(
              <div key={p.id} onClick={()=>!isActive&&setSelectedPlan(p)} style={{background:C.card,border:"1px solid "+C.border,borderRadius:16,overflow:"hidden",opacity:isActive?0.5:1,cursor:"pointer"}}>
                <div style={{padding:"14px 16px 14px"}}>
                  <div style={{display:"flex",alignItems:"center",gap:5,marginBottom:6}}>
                    <span style={{fontSize:9,fontWeight:800,color:p.color,letterSpacing:"0.12em",textTransform:"uppercase"}}>{p.name}</span>
                    <span style={{fontSize:9,color:"#2A3550",fontWeight:700}}>•</span>
                    <span style={{fontSize:9,fontWeight:800,color:p.color,letterSpacing:"0.1em",textTransform:"uppercase"}}>{p.label}</span>
                  </div>
                  <div style={{fontSize:17,fontWeight:900,color:"#FFFFFF",letterSpacing:"-0.5px",marginBottom:5}}>{p.label}</div>
                  <div style={{fontSize:11,color:"#4A5568",lineHeight:1.5,marginBottom:8,overflow:"hidden",display:"-webkit-box",WebkitLineClamp:1,WebkitBoxOrient:"vertical"}}>{exPrev}</div>
                  <div style={{display:"flex",alignItems:"center",gap:6}}>
                    <span style={{padding:"3px 8px",borderRadius:99,background:"rgba(255,255,255,0.04)",border:"1px solid "+C.border,color:"#4A5568",fontSize:9,fontWeight:700,letterSpacing:"0.08em",textTransform:"uppercase"}}>{p.exercises.length} exs</span>
                    <span style={{padding:"3px 8px",borderRadius:99,background:"rgba(255,255,255,0.04)",border:"1px solid "+C.border,color:"#4A5568",fontSize:9,fontWeight:700,letterSpacing:"0.08em",textTransform:"uppercase"}}>~{dur}min</span>
                    <button onClick={e=>{e.stopPropagation();!isActive&&startPlan(p);}} style={{flex:1,padding:"8px",background:"linear-gradient(135deg,#1E40AF,#2563EB,#3B82F6)",border:"none",borderRadius:9,color:"#fff",fontSize:11,fontWeight:800,cursor:isActive?"not-allowed":"pointer",display:"flex",alignItems:"center",justifyContent:"center",gap:6,letterSpacing:"0.08em",textTransform:"uppercase"}}>
                      <svg width="10" height="10" fill="#fff" viewBox="0 0 24 24"><path d="M8 5v14l11-7z"/></svg>
                      Iniciar
                    </button>
                  </div>
                </div>
              </div>
            );
          })}
        </div>
        {selectedPlan&&<RoutineScreen plan={selectedPlan} onClose={()=>setSelectedPlan(null)} onStart={()=>{if(!selectedPlan.isNew){startPlan(selectedPlan);setSelectedPlan(null);}}} onNavigate={onNavigate} onSaved={refreshRoutines} onDeleted={()=>{refreshRoutines();setSelectedPlan(null);}}/> }
        <BottomNav active="treino" onNavigate={onNavigate}/>
      </div>
    );
  }

  // FINISH SCREEN — percepção
  if(finishing){
    const workSets=exercises.flatMap(e=>e.activeSets.filter(s=>s.type==="work"&&s.done));
    const totalVol=workSets.reduce((s,set)=>s+set.w*set.r,0);
    const rpesets=workSets.filter(s=>s.rpe);
    const avgRpe=rpesets.length>0?(rpesets.reduce((s,s2)=>s+s2.rpe,0)/rpesets.length).toFixed(1):null;
    function saveWorkout(){
      const today=showRetro?retroDate:new Date().toISOString().slice(0,10);
      const finalDurationMin=retroDurMin!=null&&retroDurMin>0?retroDurMin:Math.round(elapsed/60);
      // Real PR detection: for each exercise trained, compare today's best 1RM
      // against the best 1RM from all previously saved/registered sessions for that exercise.
      const priorHist=HIST||{};
      const priorSaved=loadSavedSessions();
      let prCount=0;
      const exercisesData=exercises.map(e=>{
        const doneWork=e.activeSets.filter(s=>s.done&&s.type==='work');
        const bestW=Math.max(...doneWork.filter(s=>s.w>0).map(s=>s.w),0);
        const bestR=Math.max(...doneWork.filter(s=>s.r>0).map(s=>s.r),0);
        const today1rm=doneWork.filter(s=>s.w>0&&s.r>0).reduce((a,s)=>Math.max(a,orm(s.w,s.r)),0);
        if(today1rm>0){
          const histPts=(priorHist[e.name]||[]).map(s=>s.sets.filter(ss=>ss.w>0&&ss.r>0).reduce((a,ss)=>Math.max(a,orm(ss.w,ss.r)),0));
          const savedPts=priorSaved.flatMap(s=>(s.exercises||[]).filter(ex=>ex.name===e.name).flatMap(ex=>(ex.setData||[]).filter(sd=>sd.w>0&&sd.r>0).map(sd=>orm(sd.w,sd.r))));
          const priorBest=Math.max(0,...histPts,...savedPts);
          if(today1rm>priorBest) prCount++;
        }
        return{
          name:e.name,
          sets:doneWork.length,
          bestW,
          bestR,
          vol:doneWork.reduce((a,s)=>a+s.w*s.r,0),
          setData:doneWork.map(s=>({w:s.w,r:s.r,rpe:s.rpe})),
        };
      }).filter(e=>e.sets>0);
      // Estimate calories from total working sets performed (≈18 kcal/set, consistent with feed display)
      const estimatedCalories=Math.round(workSets.length*18);
      const persistSession={
        id:'w'+Date.now(),
        date:today,
        time:showRetro?retroTime:null,
        name:plan.name+(plan.label?" — "+plan.label:""),
        duration:finalDurationMin,
        exercises:exercisesData,
        totalVol:Math.round(totalVol)/1000,
        totalSets:workSets.length,
        avgRpe,
        prs:prCount,
        calories:estimatedCalories,
      };
      saveSession(persistSession);
      onWorkoutSaved&&onWorkoutSaved();
      const session={plan:plan.name,label:plan.label,elapsed:finalDurationMin*60,vol:totalVol,sets:workSets.length,avgRpe,pse:finishPse,exercises:[...exercises]};
      setFinishedSession(session);
      setFinishing(false);
      handleEnd();
    }
    return(
      <div style={{background:"#080A0E",minHeight:"100dvh",padding:"52px 20px 120px"}}>
        <div style={{textAlign:"center",marginBottom:32}}>
          <div style={{fontSize:52,marginBottom:12}}>🏋️</div>
          <div style={{fontSize:28,fontWeight:900,color:C.text,letterSpacing:"-1px",marginBottom:4}}>Treino concluído!</div>
          <div style={{fontSize:14,color:C.sub}}>{plan.name} — {plan.label}</div>
        </div>
        <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:10,marginBottom:20}}>
          {[{label:"Duração",value:fmt(elapsed)},{label:"Volume",value:(totalVol/1000).toFixed(1)+"t"},{label:"Séries",value:workSets.length},{label:"RPE Médio",value:avgRpe?avgRpe+" / 10":"—"}].map(s=>(
            <div key={s.label} style={{background:C.card,backdropFilter:"blur(20px)",border:"1px solid "+C.border,borderRadius:18,padding:"16px",textAlign:"center"}}>
              <div style={{fontSize:9,fontWeight:700,letterSpacing:"0.1em",textTransform:"uppercase",color:C.sub,marginBottom:6}}>{s.label}</div>
              <div style={{fontSize:22,fontWeight:900,color:C.blueXL}}>{s.value}</div>
            </div>
          ))}
        </div>
        <div style={{background:C.card,backdropFilter:"blur(20px)",border:"1px solid "+C.border,borderRadius:18,padding:"18px",marginBottom:20}}>
          <div style={{fontSize:14,fontWeight:800,color:C.text,marginBottom:4}}>Como foi o treino?</div>
          <div style={{fontSize:12,color:C.sub,marginBottom:14}}>Percepção de esforço geral da sessão</div>
          <div style={{display:"grid",gridTemplateColumns:"repeat(7,1fr)",gap:6,marginBottom:8}}>
            {finishPses.map(v=>{
              const col=v<=7?C.mint:v<=8.5?C.amber:C.coral;
              return(
                <button key={v} onClick={()=>setFinishPse(v)} style={{padding:"10px 4px",borderRadius:12,cursor:"pointer",background:finishPse===v?col+"33":"rgba(255,255,255,0.04)",border:"2px solid "+(finishPse===v?col:"rgba(255,255,255,0.08)"),color:finishPse===v?col:C.sub,fontSize:13,fontWeight:800,transition:"all 0.15s"}}>{v}</button>
              );
            })}
          </div>
          <div style={{display:"flex",justifyContent:"space-between",fontSize:10,color:C.muted,paddingTop:4}}>
            <span>Fácil</span><span>Moderado</span><span>Máximo</span>
          </div>
        </div>
        <div style={{background:C.card,backdropFilter:"blur(20px)",border:"1px solid "+C.border,borderRadius:18,padding:"16px 18px",marginBottom:20}}>
          <button onClick={()=>setShowRetro(v=>!v)} style={{width:"100%",background:"none",border:"none",padding:0,cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"space-between"}}>
            <div style={{display:"flex",alignItems:"center",gap:8}}>
              <span style={{fontSize:15}}>🗓️</span>
              <span style={{fontSize:14,fontWeight:700,color:C.text}}>Registrar em outro dia/horário</span>
            </div>
            <span style={{color:C.sub,fontSize:14,transform:showRetro?"rotate(180deg)":"none",transition:"transform 0.15s"}}>▾</span>
          </button>
          {showRetro&&(
            <div style={{marginTop:16,display:"flex",flexDirection:"column",gap:12}}>
              <div style={{display:"flex",gap:10}}>
                <div style={{flex:1}}>
                  <div style={{fontSize:10,fontWeight:700,color:C.sub,textTransform:"uppercase",letterSpacing:"0.06em",marginBottom:6}}>Data</div>
                  <input type="date" value={retroDate} max={new Date().toISOString().slice(0,10)} onChange={e=>setRetroDate(e.target.value)} style={{width:"100%",boxSizing:"border-box",background:C.surface,border:"1px solid "+C.border,borderRadius:12,padding:"10px 12px",fontSize:14,color:C.text,outline:"none"}}/>
                </div>
                <div style={{flex:1}}>
                  <div style={{fontSize:10,fontWeight:700,color:C.sub,textTransform:"uppercase",letterSpacing:"0.06em",marginBottom:6}}>Horário</div>
                  <input type="time" value={retroTime} onChange={e=>setRetroTime(e.target.value)} style={{width:"100%",boxSizing:"border-box",background:C.surface,border:"1px solid "+C.border,borderRadius:12,padding:"10px 12px",fontSize:14,color:C.text,outline:"none"}}/>
                </div>
              </div>
              <div>
                <div style={{fontSize:10,fontWeight:700,color:C.sub,textTransform:"uppercase",letterSpacing:"0.06em",marginBottom:6}}>Duração (minutos)</div>
                <input type="number" min="1" placeholder={String(Math.round(elapsed/60)||1)} value={retroDurMin==null?"":retroDurMin} onChange={e=>setRetroDurMin(e.target.value===""?null:parseInt(e.target.value)||0)} style={{width:"100%",boxSizing:"border-box",background:C.surface,border:"1px solid "+C.border,borderRadius:12,padding:"10px 12px",fontSize:14,color:C.text,outline:"none"}}/>
              </div>
              <div style={{fontSize:11,color:C.muted}}>Deixe a duração em branco para usar o tempo cronometrado ({fmt(elapsed)}).</div>
            </div>
          )}
        </div>
        <button onClick={saveWorkout} style={{width:"100%",padding:"16px",background:"linear-gradient(135deg,"+C.mint+",#059669)",border:"none",borderRadius:16,color:"#fff",fontSize:16,fontWeight:800,cursor:"pointer",letterSpacing:"0.02em"}}>Salvar treino →</button>
        <BottomNav active="treino" onNavigate={onNavigate}/>
      </div>
    );
  }

  // ACTIVE WORKOUT
  const totalVol=exercises.flatMap(e=>e.activeSets.filter(s=>s.type==="work"&&s.done)).reduce((s,set)=>s+set.w*set.r,0);
  const muscleGroups=[...new Set(exercises.map(e=>e.group).filter(Boolean))];
  return(
    <div style={{background:"#080A0E",minHeight:"100dvh",paddingTop:52}}>
      <style>{`
@keyframes pulse{0%,100%{opacity:1}50%{opacity:0.6}}
@keyframes prFlash{0%{transform:scale(1);box-shadow:0 0 0 0 #F59E0B00}20%{transform:scale(1.04);box-shadow:0 0 32px 6px #F59E0BCC}100%{transform:scale(1);box-shadow:0 0 12px 2px #F59E0B44}}
@keyframes prTextBounce{0%{opacity:0;transform:scale(0.8)}60%{opacity:1;transform:scale(1.08)}100%{opacity:1;transform:scale(1)}}
      `}</style>
      <div style={{position:"sticky",top:52,zIndex:50,background:"rgba(6,8,12,0.96)",backdropFilter:"blur(20px)",padding:"14px 16px 10px"}}>
        <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:6}}>
          <button onClick={()=>{setScreen("plans");onMinimize&&onMinimize();}} style={{width:30,height:30,borderRadius:"50%",background:C.card,border:"1px solid "+C.border,cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>
            <svg width="13" height="13" viewBox="0 0 14 14" fill="none"><path d="M3 5l4 4 4-4" stroke="#6B7FA3" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round"/></svg>
          </button>
          <div style={{flex:1,marginLeft:10}}>
            <div style={{fontSize:11,fontWeight:700,letterSpacing:"0.06em",textTransform:"uppercase",color:C.sub}}>{plan.name} · {plan.label}</div>
            <div style={{display:"flex",gap:4,flexWrap:"wrap",marginTop:2}}>
              {muscleGroups.map(g=><span key={g} style={{fontSize:9,fontWeight:700,color:GC[g]||C.blueL,background:(GC[g]||C.blueL)+"18",border:"1px solid "+(GC[g]||C.blueL)+"44",borderRadius:6,padding:"1px 5px"}}>{g}</span>)}
            </div>
          </div>
          <div style={{display:"flex",gap:12,alignItems:"center"}}>
            <div style={{textAlign:"center"}}>
              <div style={{fontSize:9,fontWeight:700,color:C.sub,textTransform:"uppercase",letterSpacing:"0.06em"}}>Tempo</div>
              <div style={{fontSize:16,fontWeight:800,color:C.text}}>{fmt(elapsed)}</div>
            </div>
            <div style={{textAlign:"center"}}>
              <div style={{fontSize:9,fontWeight:700,color:C.sub,textTransform:"uppercase",letterSpacing:"0.06em"}}>Séries</div>
              <div style={{fontSize:16,fontWeight:800,color:C.blueXL}}>{totalDone}<span style={{color:C.muted,fontSize:12}}>/{totalSets}</span></div>
            </div>
            <div style={{textAlign:"center"}}>
              <div style={{fontSize:9,fontWeight:700,color:C.sub,textTransform:"uppercase",letterSpacing:"0.06em"}}>Volume</div>
              <div style={{fontSize:16,fontWeight:800,color:C.mint}}>{totalVol>=1000?(totalVol/1000).toFixed(1)+"t":totalVol+"kg"}</div>
            </div>
          </div>
        </div>
        <div style={{height:2,background:C.border,borderRadius:2,marginBottom:8}}>
          <div style={{height:"100%",borderRadius:2,background:"linear-gradient(90deg,"+C.blueL+","+C.blueXL+")",width:(progress*100)+"%",transition:"width 0.4s ease"}}/>
        </div>
        <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:6}}>
          <div style={{display:"flex",gap:5,overflowX:"auto",flex:1}}>
            {exercises.map((e,i)=>{const ws=e.activeSets.filter(s=>s.type==="work");const ds=ws.filter(s=>s.done).length;const all=ds===ws.length&&ws.length>0;return(<button key={i} onClick={()=>setCurrentEx(i)} style={{padding:"4px 10px",borderRadius:99,flexShrink:0,background:all?C.mint+"22":C.card,border:"1px solid "+(all?C.mint+"66":C.border),color:all?C.mint:C.sub,fontSize:10,fontWeight:700,cursor:"pointer"}}>{e.name.split(" ")[0]} {all?"✓":ds+"/"+ws.length}</button>);})}
          </div>
          <button onClick={()=>setShowEndConfirm(true)} style={{padding:"4px 12px",borderRadius:99,background:C.coral+"22",border:"1px solid "+C.coral+"44",color:C.coral,fontSize:11,fontWeight:700,cursor:"pointer",flexShrink:0,marginLeft:8}}>Encerrar</button>
        </div>
      </div>

      <div style={{padding:"8px 12px 200px"}}>
        {exercises.map((exItem,exIdx)=>{
          const exWarm=exItem.activeSets.filter(s=>s.type==="warmup");
          const exWork=exItem.activeSets.filter(s=>s.type==="work");
          const allDone=exWork.filter(s=>s.done).length===exWork.length&&exWork.length>0;
          const exVol=exWork.filter(s=>s.done).reduce((s,set)=>s+set.w*set.r,0);
          const exDone=exWork.filter(s=>s.done).length;
          return(
            <div key={exIdx} style={{marginBottom:6,background:C.card,border:"1px solid "+(allDone?"rgba(16,185,129,0.3)":"rgba(255,255,255,0.06)"),borderRadius:12,overflow:"hidden",transition:"border-color 0.3s"}}>
              <div style={{padding:"8px 10px 6px",borderBottom:"1px solid "+C.border}}>
                <div style={{display:"flex",alignItems:"center",justifyContent:"space-between"}}>
                  <div style={{display:"flex",alignItems:"center",gap:6,flex:1,minWidth:0}}>
                    <div style={{width:6,height:6,borderRadius:"50%",background:GC[exItem.group]||C.blueL,flexShrink:0}}/>
                    <div style={{fontSize:13,fontWeight:800,color:allDone?C.mint:C.text,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{exItem.name}</div>
                    {allDone&&<span style={{color:C.mint,fontSize:10,flexShrink:0}}>✓</span>}
                  </div>
                  <div style={{display:"flex",alignItems:"center",gap:6,flexShrink:0}}>
                    {exDone>0&&<span style={{fontSize:10,color:C.mint,fontWeight:700}}>{exVol}kg</span>}
                    <span style={{fontSize:10,color:C.sub}}>{exDone}/{exWork.length}</span>
                    <button onClick={()=>{setCurrentEx(exIdx);setShowExMenu(true);}} style={{width:22,height:22,borderRadius:99,background:"none",border:"none",color:C.sub,fontSize:15,cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center"}}>⋯</button>
                  </div>
                </div>
                <button onClick={()=>setRestPickerEi(exIdx)} style={{display:"flex",alignItems:"center",gap:4,background:"none",border:"none",padding:0,paddingLeft:12,marginTop:1,cursor:"pointer"}}><span style={{fontSize:9,color:C.muted}}>Descanso: {exItem.rest==null?"Off":(exItem.rest>=60?Math.floor(exItem.rest/60)+"min"+(exItem.rest%60>0?" "+exItem.rest%60+"s":""):exItem.rest+"s")}</span><span style={{fontSize:8,color:C.muted,marginLeft:2}}>✎</span></button>
              </div>
              <div style={{padding:"4px 10px 0"}}><ExerciseHistory exName={exItem.name} currentSets={exWork}/></div>
              {exWarm.length>0&&<WarmupSection exWarm={exWarm} exIdx={exIdx} updateSet={updateSet} markDone={markDone}/>}
              <div style={{padding:"3px 10px 0"}}>
                <div style={{display:"grid",gridTemplateColumns:"24px 1fr 1fr 1fr 30px 30px",gap:3,marginBottom:2,paddingBottom:2,borderBottom:"1px solid rgba(255,255,255,0.04)"}}>
                  {["#","Ant.","KG","Reps","RPE",""].map((h,i)=><div key={i} style={{fontSize:7,fontWeight:700,letterSpacing:"0.08em",textTransform:"uppercase",color:C.muted,textAlign:"center"}}>{h}</div>)}
                </div>
                {exWork.map((set,wi)=>{
                  const si=exWarm.length+wi;
                  const estORM=set.w>0&&set.r>0?orm(set.w,set.r):null;
                  const rpeColor=set.rpe?(set.rpe<=7?C.mint:set.rpe<=8.5?C.amber:C.coral):null;
                  const setORM=set.w>0&&set.r>0?orm(set.w,set.r):0;
                  const bestORM=getBestORM(exItem.name);const bestW=getBestW(exItem.name);
                  const sessORM=exWork.slice(0,wi).filter(s=>s.done&&s.w>0&&s.r>0).reduce((a,s)=>Math.max(a,orm(s.w,s.r)),0);
                  const sessW=exWork.slice(0,wi).filter(s=>s.done&&s.w>0).reduce((a,s)=>Math.max(a,s.w),0);
                  const setIsOrmPR=set.done&&setORM>bestORM&&setORM>sessORM&&setORM>0;
                  const setIsWPR=set.done&&set.w>bestW&&set.w>sessW&&set.w>0;
                  const setIsPR=setIsOrmPR||setIsWPR;
                  const prevSess=(HIST[exItem.name]||[]).slice(-1)[0];
                  const prevSet=prevSess?.sets[wi];
                  const prevStr=prevSet?prevSet.w+"×"+prevSet.r+(prevSet.rpe?" @"+prevSet.rpe:""):"—";
                  const isAnim=prAnimSi&&prAnimSi.ei===exIdx&&prAnimSi.si===si;
                  const rowBg=set.done?(setIsPR?"linear-gradient(135deg,#92400E33,#B4530926,#F59E0B1C)":C.mint+"0F"):"transparent";
                  const rowBorder=set.done?(setIsPR?"1px solid "+C.amber+"66":"1px solid "+C.mint+"22"):"1px solid transparent";
                  return(
                    <div key={wi} style={{marginBottom:2}}>
                      {setIsPR&&<div style={{display:"flex",alignItems:"center",gap:5,paddingLeft:28,paddingBottom:2}}>
                        <span style={{fontSize:8,fontWeight:700,color:C.amber,letterSpacing:"0.06em",textTransform:"uppercase"}}>🏆 {setIsOrmPR?"Novo PR · 1RM est.":"Novo PR · Carga"}</span>
                        <span style={{fontSize:8,color:C.amber+"88"}}>{setIsOrmPR?`${setORM}kg`:`${set.w}kg`} ant. {setIsOrmPR?bestORM:bestW}kg</span>
                      </div>}
                      <div style={{display:"grid",gridTemplateColumns:"24px 1fr 1fr 1fr 30px 30px",gap:3,alignItems:"center",padding:"2px 0",borderRadius:8,background:setIsPR?"rgba(245,158,11,0.06)":set.done?"rgba(16,185,129,0.04)":"transparent",border:setIsPR?"1px solid "+C.amber+"44":set.done?"1px solid "+C.mint+"18":"1px solid transparent",animation:isAnim?"prFlash 0.7s ease-out 1 forwards":"none",transition:"background 0.25s,border 0.25s"}}>
                        <div style={{width:24,height:24,borderRadius:6,background:setIsPR?"linear-gradient(135deg,#B45309,#F59E0B)":set.done?C.mint+"33":C.blueM+"22",border:"1px solid "+(setIsPR?"transparent":set.done?C.mint+"44":C.borderL),display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>
                          {setIsPR?<span style={{fontSize:11}}>🏆</span>:<span style={{fontSize:10,fontWeight:800,color:set.done?C.mint:C.blueXL}}>{wi+1}</span>}
                        </div>
                        <div style={{fontSize:9,color:C.muted,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap",textAlign:"center"}}>{prevStr}</div>
                        <SmartInput value={set.w} onChange={v=>!set.done&&updateSet(exIdx,si,"w",v)} readOnly={set.done} unit="kg" color={setIsPR?C.amber:set.done?C.mint:C.text} compact/>
                        <SmartInput value={set.r} onChange={v=>!set.done&&updateSet(exIdx,si,"r",v)} readOnly={set.done} unit="reps" integer color={setIsPR?C.amber:set.done?C.mint:C.text} compact/>
                        <button onClick={()=>!set.done&&(setCurrentEx(exIdx),setRpeModal({ei:exIdx,si,rest:exItem.rest}))} style={{height:24,borderRadius:6,cursor:set.done?"default":"pointer",background:set.rpe?(rpeColor+"22"):C.surface,border:"1px solid "+(set.rpe?(rpeColor+"66"):C.border),color:set.rpe?rpeColor:C.muted,fontSize:set.rpe?9:7,fontWeight:800,display:"flex",alignItems:"center",justifyContent:"center"}}>{set.rpe||"RPE"}</button>
                        <button onClick={()=>markDone(si,exIdx)} style={{height:24,borderRadius:6,background:set.done?(setIsPR?C.amber+"33":C.mint+"33"):C.surface,border:"2px solid "+(set.done?(setIsPR?C.amber:C.mint):C.border),color:set.done?(setIsPR?C.amber:C.mint):C.muted,fontSize:13,cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center",transition:"all 0.15s"}}>{set.done?"✓":"○"}</button>
                      </div>
                      {estORM&&!set.done&&!setIsPR&&<div style={{fontSize:8,color:C.muted,paddingLeft:28,paddingTop:1}}>1RM ~{estORM}kg</div>}
                    </div>
                  );
                })}
                <button onClick={()=>{setCurrentEx(exIdx);const work=exItem.activeSets.filter(s=>s.type==="work");const last=work[work.length-1]||{w:0,r:8};setExercises(prev=>prev.map((e,i)=>i!==exIdx?e:{...e,activeSets:[...e.activeSets,{w:last.w,r:last.r,done:false,type:"work",rpe:null}]}));}} style={{width:"100%",padding:"5px",background:"none",border:"1px dashed "+C.border,borderRadius:7,color:C.muted,fontSize:10,fontWeight:600,cursor:"pointer",margin:"4px 0"}}>+ Adicionar série</button>
              </div>
            </div>
          );
        })}
        <button onClick={()=>setShowGallery(true)} style={{width:"100%",padding:"14px",background:"none",border:"1px dashed "+C.blueL+"88",borderRadius:14,color:C.blueXL,fontSize:14,fontWeight:700,cursor:"pointer",marginBottom:16}}>+ Adicionar exercício</button>
        <button onClick={()=>setFinishing(true)} style={{width:"100%",padding:"16px",background:C.mint,border:"none",borderRadius:14,color:"#fff",fontSize:16,fontWeight:700,cursor:"pointer"}}>Finalizar treino ✓</button>
      </div>

      {rpeModal&&<RPEModal onSelect={handleRpeSelect} onSkip={()=>{const{rest}=rpeModal;setRpeModal(null);if(rest!=null)setRestTimer({seconds:rest});}}/>}
      {restTimer&&!rpeModal&&<RestTimer seconds={restTimer.seconds} onDone={()=>setRestTimer(null)} onSkip={()=>setRestTimer(null)}/>}
      {restPickerEi!=null&&<RestTimePickerModal initial={exercises[restPickerEi].rest} onClose={()=>setRestPickerEi(null)} onSelect={(val)=>{setExercises(prev=>prev.map((e,i)=>i!==restPickerEi?e:{...e,rest:val}));setRestPickerEi(null);}}/>}
      <PRToast pr={prToast}/>
      {showGallery&&<ExerciseGallery onAdd={addExercise} onClose={()=>setShowGallery(false)}/>}
      {showExMenu&&ex&&(
        <div style={{position:"fixed",inset:0,zIndex:500,background:"#00000088",backdropFilter:"blur(4px)",display:"flex",alignItems:"flex-end"}} onClick={()=>setShowExMenu(false)}>
          <div style={{width:"100%",background:C.surface,borderTop:"1px solid "+C.border,borderRadius:"20px 20px 0 0",padding:"8px 0 32px"}} onClick={e=>e.stopPropagation()}>
            <div style={{width:36,height:4,borderRadius:2,background:C.border,margin:"10px auto 20px"}}/>
            <div style={{fontSize:13,fontWeight:700,color:C.sub,padding:"0 20px 12px"}}>{ex.name.split("(")[0].trim()}</div>
            {[{icon:"↕",label:"Reordenar exercícios",action:()=>{setReorderList([...exercises]);setShowExMenu(false);setShowReorder(true);}},{icon:"⟳",label:"Substituir exercício",action:()=>{setShowExMenu(false);setShowGallery(true);}},{icon:"+",label:"Adicionar supersérie",action:()=>setShowExMenu(false)}].map(({icon,label,action})=>(
              <button key={label} onClick={action} style={{width:"100%",padding:"16px 20px",background:"none",border:"none",borderBottom:"1px solid "+C.border,cursor:"pointer",display:"flex",alignItems:"center",gap:16,textAlign:"left"}}>
                <span style={{fontSize:18,color:C.sub,width:24,textAlign:"center"}}>{icon}</span>
                <span style={{fontSize:15,fontWeight:600,color:C.text}}>{label}</span>
              </button>
            ))}
            <button onClick={()=>{if(exercises.length>1){setExercises(prev=>prev.filter((_,i)=>i!==currentEx));setCurrentEx(i=>Math.max(0,i-1));}setShowExMenu(false);}} style={{width:"100%",padding:"16px 20px",background:"none",border:"none",cursor:"pointer",display:"flex",alignItems:"center",gap:16,textAlign:"left"}}>
              <span style={{fontSize:18,color:C.coral,width:24,textAlign:"center"}}>✕</span>
              <span style={{fontSize:15,fontWeight:600,color:C.coral}}>Remover exercício</span>
            </button>
          </div>
        </div>
      )}
      {showReorder&&(
        <div style={{position:"fixed",inset:0,zIndex:500,background:C.bg,display:"flex",flexDirection:"column"}}>
          <div style={{background:C.surface,padding:"52px 20px 16px",borderBottom:"1px solid "+C.border,textAlign:"center"}}><div style={{fontSize:17,fontWeight:700,color:C.text}}>Reordenar</div></div>
          <div style={{flex:1,overflow:"auto",padding:"8px 0"}}>
            {reorderList.map((exItem,i)=>(
              <div key={i} style={{display:"flex",alignItems:"center",gap:12,padding:"12px 20px",borderBottom:"1px solid "+C.border+"44"}}>
                <div style={{display:"flex",flexDirection:"column",gap:2,flexShrink:0}}>
                  <button disabled={i===0} onClick={()=>setReorderList(prev=>{const a=[...prev];[a[i-1],a[i]]=[a[i],a[i-1]];return a;})} style={{width:32,height:28,background:i===0?C.border:C.card,border:"1px solid "+C.border,borderRadius:7,color:i===0?C.muted:C.text,fontSize:13,cursor:i===0?"default":"pointer",display:"flex",alignItems:"center",justifyContent:"center"}}>▲</button>
                  <button disabled={i===reorderList.length-1} onClick={()=>setReorderList(prev=>{const a=[...prev];[a[i],a[i+1]]=[a[i+1],a[i]];return a;})} style={{width:32,height:28,background:i===reorderList.length-1?C.border:C.card,border:"1px solid "+C.border,borderRadius:7,color:i===reorderList.length-1?C.muted:C.text,fontSize:13,cursor:i===reorderList.length-1?"default":"pointer",display:"flex",alignItems:"center",justifyContent:"center"}}>▼</button>
                </div>
                <div style={{width:8,height:8,borderRadius:"50%",background:GC[exItem.group]||C.blueL,flexShrink:0}}/>
                <div style={{flex:1,fontSize:15,fontWeight:600,color:C.text}}>{exItem.name}</div>
                <div style={{color:C.muted,fontSize:22,cursor:"grab",userSelect:"none",flexShrink:0}}>≡</div>
              </div>
            ))}
          </div>
          <div style={{padding:"16px 20px 40px",display:"flex",gap:10,background:C.surface,borderTop:"1px solid "+C.border}}>
            <button onClick={()=>setShowReorder(false)} style={{flex:1,padding:"14px",background:C.card,border:"1px solid "+C.border,borderRadius:14,color:C.sub,fontSize:14,fontWeight:600,cursor:"pointer"}}>Cancelar</button>
            <button onClick={()=>{setExercises(reorderList);setCurrentEx(0);setShowReorder(false);}} style={{flex:2,padding:"14px",background:C.blueL,border:"none",borderRadius:14,color:"#fff",fontSize:15,fontWeight:700,cursor:"pointer"}}>Feito</button>
          </div>
        </div>
      )}
      {showEndConfirm&&(
        <div style={{position:"fixed",inset:0,zIndex:600,background:"#000000CC",display:"flex",alignItems:"center",justifyContent:"center",padding:24}}>
          <div style={{background:C.card,border:"1px solid "+C.border,borderRadius:24,padding:28,width:"100%",maxWidth:320,textAlign:"center"}}>
            <div style={{fontSize:22,fontWeight:800,color:C.text,marginBottom:8}}>Encerrar treino?</div>
            <div style={{fontSize:14,color:C.sub,marginBottom:24}}>O progresso atual será salvo.</div>
            <div style={{display:"flex",gap:10}}>
              <button onClick={()=>setShowEndConfirm(false)} style={{flex:1,padding:"14px",background:C.surface,border:"1px solid "+C.border,borderRadius:14,color:C.sub,fontSize:14,fontWeight:600,cursor:"pointer"}}>Cancelar</button>
              <button onClick={()=>{setShowEndConfirm(false);setFinishing(true);}} style={{flex:1,padding:"14px",background:C.coral,border:"none",borderRadius:14,color:"#fff",fontSize:14,fontWeight:700,cursor:"pointer"}}>Encerrar</button>
            </div>
          </div>
        </div>
      )}
      <BottomNav active="treino" onNavigate={onNavigate}/>
    </div>
  );
}

// ══════════════════════════════════════════════════════════════
// EXERCÍCIO SCREEN
// ══════════════════════════════════════════════════════════════
const EXERCISES_INFO = {
  "Supino (Barra)":{group:"Peito",secondary:["Tríceps","Ombros"],type:"Composto",equipment:"Barra + Banco",muscles:["Peitoral maior","Tríceps braquial","Deltoide anterior"],instructions:["Deite no banco com olhos abaixo da barra. Pegada levemente mais larga que os ombros.","Retire a barra com braços estendidos, alinhada ao peito.","Desça controlado até tocar o peito, cotovelos a 45-75°.","Empurre de volta em linha reta até extensão completa."],tips:"Mantenha escápulas retraídas e pés firmes no chão durante todo o movimento."},
  "Levantamento Terra (Barra)":{group:"Costas",secondary:["Pernas","Core"],type:"Composto",equipment:"Barra",muscles:["Latíssimo do dorso","Trapézio","Glúteo máximo","Isquiotibiais"],instructions:["Barra sobre os metatarsos. Pegada na largura dos ombros.","Quadril para baixo, peito para fora, barra encostada na perna.","Empurre o chão mantendo a barra colada ao corpo.","Estenda quadril e joelhos simultaneamente."],tips:"A barra deve raspar a canela na subida."},
  "Agachamento (Barra)":{group:"Pernas",secondary:["Core","Costas"],type:"Composto",equipment:"Barra + Rack",muscles:["Quadríceps","Glúteo máximo","Isquiotibiais"],instructions:["Barra apoiada nos trapézios, pés na largura dos ombros.","Desça mantendo joelhos alinhados com os pés.","Coxa paralela ou abaixo do paralelo com o chão.","Empurre de volta através dos calcanhares."],tips:"Respire fundo antes de descer e expire no esforço."},
  "Desenvolvimento (Halter)":{group:"Ombros",secondary:["Tríceps"],type:"Composto",equipment:"Halter",muscles:["Deltoide médio","Deltoide anterior","Trapézio superior"],instructions:["Sentado, halteres na altura dos ombros, palmas para frente.","Empurre diretamente acima até extensão completa.","Desça controlado até posição inicial."],tips:"Não arquee a lombar — core ativado durante todo o movimento."},
  "Barra Fixa":{group:"Costas",secondary:["Bíceps"],type:"Composto",equipment:"Barra Fixa",muscles:["Latíssimo do dorso","Romboides","Bíceps braquial"],instructions:["Pegada supinada ou pronada, ligeiramente mais larga que ombros.","Retraia as escápulas antes de puxar.","Puxe o queixo acima da barra contraindo o dorsal.","Desça controlado até extensão completa."],tips:"Pense em trazer os cotovelos para os bolsos."},
};

function ExercicioScreen({name,onNavigate,onBack}){
  const[tab,setTab]=useState("resumo");
  const[chartMode,setChartMode]=useState("carga");
  const[chartRange,setChartRange]=useState("3m");
  const exName=name||"Supino (Barra)";
  const info=EXERCISES_INFO[exName]||EXERCISES_INFO["Supino (Barra)"];
  const gc=GC[info.group]||C.blueL;
  const hist=HIST[exName]||[];
  const allSets=hist.flatMap(s=>s.sets);
  const bestW=allSets.reduce((a,s)=>Math.max(a,s.w||0),0);
  const bestORM=allSets.reduce((a,s)=>s.w>0&&s.r>0?Math.max(a,orm(s.w,s.r)):a,0);

  const nPoints={all:hist.length,"1a":12,"3m":6,"1m":4}[chartRange]||6;
  const filteredHist=hist.slice(-nPoints);

  const chartData=useMemo(()=>{
    if(!filteredHist.length)return[];
    return filteredHist.map(s=>({x:s.d,y:chartMode==="carga"?Math.max(...s.sets.map(ss=>ss.w||0)):Math.max(...s.sets.map(ss=>ss.w>0&&ss.r>0?orm(ss.w,ss.r):0))}));
  },[filteredHist,chartMode]);

  const maxY=Math.max(...chartData.map(d=>d.y),0.01);
  const minY=Math.min(...chartData.map(d=>d.y),0);
  const W=400,H=140,PAD=10;

  const px=(i)=>chartData.length>1?i*(W-PAD*2)/(chartData.length-1)+PAD:W/2;
  const py=(v)=>H-PAD-((v-minY)/(maxY-minY||1))*(H-PAD*2);

  const goBack=()=>{if(onBack)onBack();else onNavigate("treino");};

  return(
    <div style={{background:"#080A0E",minHeight:"100dvh",display:"flex",flexDirection:"column",paddingBottom:100,paddingTop:52}}>
      <div style={{position:"sticky",top:52,zIndex:50,background:"rgba(6,8,12,0.96)",backdropFilter:"blur(20px)"}}>
        <div style={{padding:"14px 16px 0"}}>
          <div style={{display:"flex",alignItems:"center",gap:12,marginBottom:10}}>
            <button onClick={goBack} style={{width:34,height:34,borderRadius:"50%",background:C.card,border:"1px solid "+C.border,color:C.sub,fontSize:20,cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0}}>‹</button>
            <div>
              <div style={{fontSize:11,fontWeight:700,letterSpacing:"0.08em",textTransform:"uppercase",color:gc}}>{info.group}</div>
              <div style={{fontSize:20,fontWeight:800,color:C.text,letterSpacing:"-0.5px"}}>{exName}</div>
            </div>
          </div>
          <div style={{display:"flex",borderBottom:"1px solid "+C.border}}>
            {["resumo","historico","instrucoes"].map(t=>(
              <button key={t} onClick={()=>setTab(t)} style={{flex:1,padding:"10px 0",background:"none",border:"none",cursor:"pointer",fontSize:13,fontWeight:tab===t?700:500,color:tab===t?C.blueXL:C.sub,borderBottom:tab===t?"2px solid "+C.blueXL:"2px solid transparent",marginBottom:-1}}>
                {t==="resumo"?"Resumo":t==="historico"?"Histórico":"Instruções"}
              </button>
            ))}
          </div>
        </div>
      </div>
      <div style={{flex:1,overflowY:"auto",padding:"0 16px 20px"}}>
        {tab==="resumo"&&<div>
          <div style={{height:200,background:C.surface,display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",margin:"16px 0",borderRadius:16,border:"1px solid "+C.border}}>
            <div style={{width:52,height:52,borderRadius:"50%",background:C.card,border:"1px solid "+C.border,display:"flex",alignItems:"center",justifyContent:"center",marginBottom:10}}>
              <svg width="20" height="20" viewBox="0 0 24 24" fill="none"><path d="M5 3l14 9-14 9V3z" fill={C.sub}/></svg>
            </div>
            <div style={{fontSize:12,color:C.muted}}>Vídeo demonstrativo em breve</div>
          </div>
          <div style={{background:C.card,border:"1px solid "+C.border,borderRadius:16,padding:16,marginBottom:12}}>
            <div style={{display:"flex",flexWrap:"wrap",gap:8,marginBottom:8}}>
              {(info.muscles||[]).map(m=><span key={m} style={{padding:"4px 12px",borderRadius:99,background:gc+"22",border:"1px solid "+gc+"44",fontSize:12,color:gc,fontWeight:600}}>{m}</span>)}
            </div>
            {info.secondary&&info.secondary.length>0&&<div style={{fontSize:12,color:C.sub}}>Secundário: {info.secondary.join(", ")}</div>}
            <div style={{fontSize:11,color:C.muted,marginTop:4}}>{info.type} · {info.equipment}</div>
          </div>
          <div style={{display:"grid",gridTemplateColumns:"1fr 1fr 1fr",gap:8,marginBottom:12}}>
            {[{l:"RECORDE 1RM",v:bestORM>0?bestORM+"kg":"—",c:C.amber},{l:"MAIOR CARGA",v:bestW>0?bestW+"kg":"—",c:C.blueXL},{l:"SESSÕES",v:hist.length,c:C.mint}].map(s=>(
              <div key={s.l} style={{background:C.card,border:"1px solid "+C.border,borderRadius:14,padding:"12px 10px",textAlign:"center"}}>
                <div style={{fontSize:9,fontWeight:700,letterSpacing:"0.08em",textTransform:"uppercase",color:C.muted,marginBottom:6}}>{s.l}</div>
                <div style={{fontSize:20,fontWeight:900,color:s.c}}>{s.v}</div>
              </div>
            ))}
          </div>
          {chartData.length>0&&<div style={{background:C.card,border:"1px solid "+C.border,borderRadius:16,padding:16,marginBottom:12}}>
            <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:8}}>
              <div>
                <div style={{fontSize:20,fontWeight:900,color:C.text,letterSpacing:"-0.5px"}}>{chartData[chartData.length-1]?.y}kg</div>
                <div style={{fontSize:10,color:C.blueXL}}>{fmtDate(chartData[chartData.length-1]?.x)}</div>
              </div>
              <div style={{display:"flex",gap:4}}>
                {["1m","3m","1a","all"].map(r=>(
                  <button key={r} onClick={()=>setChartRange(r)} style={{padding:"4px 8px",borderRadius:99,fontSize:10,fontWeight:700,cursor:"pointer",background:chartRange===r?C.blueXL:"none",border:"1px solid "+(chartRange===r?C.blueXL:C.border),color:chartRange===r?"#fff":C.sub}}>{r==="all"?"Tudo":r==="1a"?"Ano":r==="3m"?"3M":"1M"}</button>
                ))}
              </div>
            </div>
            <div style={{display:"flex",gap:5,marginBottom:10}}>
              {["carga","1rm"].map(m=><button key={m} onClick={()=>setChartMode(m)} style={{padding:"4px 10px",borderRadius:99,fontSize:11,fontWeight:700,cursor:"pointer",background:chartMode===m?C.blueM+"66":C.surface,border:"1px solid "+(chartMode===m?C.blueL:C.border),color:chartMode===m?C.blueXL:C.sub}}>{m==="carga"?"Maior Peso":"1RM Estimado"}</button>)}
            </div>
            {/* Chart with scale and labels */}
            <div style={{position:"relative"}}>
              {/* Y scale */}
              <div style={{position:"absolute",left:0,top:0,bottom:20,width:36,display:"flex",flexDirection:"column",justifyContent:"space-between",pointerEvents:"none"}}>
                {[maxY,Math.round((maxY+minY)/2),minY].map((v,i)=><span key={i} style={{fontSize:8,color:C.muted,lineHeight:1}}>{v}kg</span>)}
              </div>
              <div style={{marginLeft:40}}>
                <svg width="100%" height={H} viewBox={`0 0 ${W} ${H}`} preserveAspectRatio="none" style={{overflow:"visible"}}>
                  {/* Grid lines */}
                  {[0,0.5,1].map((f,i)=><line key={i} x1={PAD} y1={PAD+(H-PAD*2)*f} x2={W-PAD} y2={PAD+(H-PAD*2)*f} stroke={C.border} strokeWidth="1" strokeDasharray="4,4"/>)}
                  {/* Area gradient */}
                  <defs><linearGradient id="exg" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor={gc} stopOpacity="0.3"/><stop offset="100%" stopColor={gc} stopOpacity="0"/></linearGradient></defs>
                  {chartData.length>1&&<polygon points={[...chartData.map((d,i)=>`${px(i)},${py(d.y)}`),`${px(chartData.length-1)},${H-PAD}`,`${px(0)},${H-PAD}`].join(" ")} fill="url(#exg)"/>}
                  {/* Line */}
                  <polyline points={chartData.map((d,i)=>`${px(i)},${py(d.y)}`).join(" ")} fill="none" stroke={gc} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                  {/* Points + labels */}
                  {chartData.map((d,i)=>(
                    <g key={i}>
                      <circle cx={px(i)} cy={py(d.y)} r="4" fill={gc} stroke={C.bg} strokeWidth="2"/>
                      <text x={px(i)} y={py(d.y)-8} textAnchor="middle" fontSize="9" fill={C.sub}>{d.y}kg</text>
                    </g>
                  ))}
                </svg>
                {/* X labels */}
                <div style={{display:"flex",justifyContent:"space-between",marginTop:2}}>
                  <span style={{fontSize:9,color:C.muted}}>{fmtDate(chartData[0]?.x)}</span>
                  <span style={{fontSize:9,color:C.muted}}>{fmtDate(chartData[chartData.length-1]?.x)}</span>
                </div>
              </div>
            </div>
          </div>}
        </div>}
        {tab==="historico"&&<div style={{paddingTop:16}}>
          {!hist.length?<div style={{textAlign:"center",padding:40,color:C.muted}}>Nenhum histórico ainda</div>:
          [...hist].reverse().map((session,i)=>{
            const bestSet=session.sets.reduce((a,b)=>orm(b.w,b.r)>orm(a.w,a.r)?b:a,session.sets[0]);
            const avgRpe=session.sets.filter(s=>s.rpe).length>0?(session.sets.filter(s=>s.rpe).reduce((s,s2)=>s+s2.rpe,0)/session.sets.filter(s=>s.rpe).length).toFixed(1):null;
            const rpeColor=avgRpe?(avgRpe<=7?C.mint:avgRpe<=8.5?C.amber:C.coral):null;
            return(<div key={i} style={{background:C.card,border:"1px solid "+C.border,borderRadius:16,padding:16,marginBottom:10}}>
              <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:10}}>
                <div style={{fontSize:13,fontWeight:700,color:C.text}}>{fmtDate(session.d)}</div>
                {avgRpe&&<div style={{fontSize:12,fontWeight:700,color:rpeColor}}>RPE {avgRpe}</div>}
              </div>
              {session.sets.map((set,si)=>(
                <div key={si} style={{display:"flex",alignItems:"center",gap:10,padding:"6px 0",borderTop:si>0?"1px solid "+C.border+"44":"none"}}>
                  <div style={{width:24,fontSize:11,color:C.muted,fontWeight:700}}>{si+1}</div>
                  <div style={{flex:1,fontSize:14,color:C.text,fontWeight:600}}>{set.w>0?set.w+"kg":"BW"} × {set.r}</div>
                  {set.rpe&&<div style={{fontSize:11,color:set.rpe<=7?C.mint:set.rpe<=8.5?C.amber:C.coral,fontWeight:700}}>@{set.rpe}</div>}
                </div>
              ))}
            </div>);
          })}
        </div>}
        {tab==="instrucoes"&&<div style={{paddingTop:16}}>
          <div style={{background:C.card,border:"1px solid "+C.border,borderRadius:16,padding:16,marginBottom:12}}>
            <div style={{fontSize:13,fontWeight:700,color:C.sub,marginBottom:12,letterSpacing:"0.06em",textTransform:"uppercase"}}>Execução</div>
            {(info.instructions||[]).map((step,i)=>(
              <div key={i} style={{display:"flex",gap:12,marginBottom:12}}>
                <div style={{width:24,height:24,borderRadius:"50%",background:gc+"22",border:"1px solid "+gc+"44",display:"flex",alignItems:"center",justifyContent:"center",fontSize:11,fontWeight:800,color:gc,flexShrink:0}}>{i+1}</div>
                <div style={{fontSize:14,color:C.text,flex:1,lineHeight:1.5}}>{step}</div>
              </div>
            ))}
          </div>
          {info.tips&&<div style={{background:C.amber+"11",border:"1px solid "+C.amber+"33",borderRadius:16,padding:16}}>
            <div style={{fontSize:12,fontWeight:700,color:C.amber,marginBottom:6}}>💡 Dica do coach</div>
            <div style={{fontSize:14,color:C.text,lineHeight:1.5}}>{info.tips}</div>
          </div>}
        </div>}
      </div>
      <BottomNav active="treino" onNavigate={onNavigate}/>
    </div>
  );
}

// ══════════════════════════════════════════════════════════════
// HISTÓRICO SCREEN
// ══════════════════════════════════════════════════════════════
function HistoricoScreen({onNavigate}){
  const[filter,setFilter]=useState("todos");
  const[detail,setDetail]=useState(null);
  const filters=["todos","push","pull","legs","upper"];
  const typeMap={"push":["Peito","Triceps","Ombros"],"pull":["Costas","Biceps"],"legs":["Pernas"],"upper":["Peito","Costas","Ombros","Biceps","Triceps"]};
  const filtered=filter==="todos"?FEED:FEED.filter(s=>s.exercises.some(ex=>{const g=EX_GROUP[ex.name];return(typeMap[filter]||[]).includes(g);}));
  const totalVol=FEED.reduce((a,s)=>a+s.totalVol,0);
  const totalPRs=FEED.reduce((a,s)=>a+s.prs,0);

  if(detail) return <WorkoutDetail session={detail} onClose={()=>setDetail(null)}/>;

  return(
    <div style={{background:"#080A0E",minHeight:"100dvh",paddingTop:52}}>
      <div style={{position:"sticky",top:52,zIndex:50,background:"rgba(5,6,9,0.97)",backdropFilter:"blur(24px)",WebkitBackdropFilter:"blur(24px)",padding:"14px 16px 14px"}}>
        <div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-end",marginBottom:14}}>
          <div style={{fontSize:28,fontWeight:900,color:"#FFFFFF",letterSpacing:"-0.5px"}}>Histórico</div>
          <div style={{textAlign:"right"}}>
            <div style={{fontSize:22,fontWeight:900,color:C.blueXL,letterSpacing:"-0.5px"}}>{FEED.length}<span style={{fontSize:11,color:C.sub,fontWeight:500}}> treinos</span></div>
          </div>
        </div>
        <div style={{display:"flex",gap:6,overflowX:"auto",paddingBottom:2}}>
          {filters.map(f=><button key={f} onClick={()=>setFilter(f)} style={{padding:"6px 16px",borderRadius:99,flexShrink:0,cursor:"pointer",background:filter===f?"#1E40AF30":C.card,border:"1px solid "+(filter===f?C.blueL+"60":C.border),color:filter===f?C.blueXL:"#4A5568",fontSize:11,fontWeight:filter===f?700:500,textTransform:"uppercase",letterSpacing:"0.06em"}}>{f==="todos"?"Todos":f.toUpperCase()}</button>)}
        </div>
      </div>
      <div style={{padding:"16px 16px 100px"}}>
        <div style={{display:"grid",gridTemplateColumns:"1fr 1fr 1fr",gap:8,marginBottom:16}}>
          {[{l:"Treinos",v:FEED.length,c:C.blueXL},{l:"Volume",v:Math.round(totalVol*10)/10+"t",c:C.mint},{l:"PRs",v:totalPRs,c:C.amber}].map(s=>(
            <div key={s.l} style={{background:C.card,border:"1px solid "+C.border,borderRadius:16,padding:"14px 12px",textAlign:"center"}}>
              <div style={{fontSize:9,fontWeight:700,letterSpacing:"0.1em",textTransform:"uppercase",color:"#2A3550",marginBottom:6}}>{s.l}</div>
              <div style={{fontSize:20,fontWeight:900,color:s.c}}>{s.v}</div>
            </div>
          ))}
        </div>
        {filtered.map((session,i)=><FeedCard key={i} session={session} onOpen={setDetail}/>)}
      </div>
      <BottomNav active="progresso" onNavigate={onNavigate}/>
    </div>
  );
}


// ─── SPIDER CHART ────────────────────────────────────────────
// Layout (flat-top hexagon, offset=-150deg):
//   Peito(top-L)  Costas(top-R)
//   Core(mid-L)   Pernas(mid-R)
//   Braços(bot-L) Ombros(bot-R)
function SpiderChart({muscles,size=280}){
  // Order must match vertex positions clockwise from top-left
  // flat-top: vertices at -150,-90,-30,30,90,150 degrees
  // So: Peito(-150=top-L), Core(-90=left), Braços(-30→actually bottom-L needs 150)
  // Correct flat-top clockwise: top-L, top-R, right, bot-R, bot-L, left
  // = Peito, Costas, Pernas, Ombros, Braços, Core
  const order=["Peito","Costas","Pernas","Ombros","Braços","Core"];
  const sm=order.map(g=>muscles.find(m=>m.g===g)||{g,pct:0,color:C.coral});
  const N=sm.length,CX=size/2,CY=size/2,R=size*0.34,LD=size*0.44;
  // flat-top: first vertex at -150° (top-left), step 60°
  const ang=(i)=>(i/N)*Math.PI*2+(-150*Math.PI/180);
  const ox=(i)=>CX+R*Math.cos(ang(i));
  const oy=(i)=>CY+R*Math.sin(ang(i));
  const vx=(m,i)=>CX+R*(m.pct/100)*Math.cos(ang(i));
  const vy=(m,i)=>CY+R*(m.pct/100)*Math.sin(ang(i));
  const rings=[0.25,0.5,0.75,1];
  const axes=sm.map((_,i)=>i);
  const dataStr=sm.map((m,i)=>vx(m,i)+","+vy(m,i)).join(" ");
  return(
    <svg width={size} height={size} viewBox={"0 0 "+size+" "+size} style={{display:"block",margin:"0 auto"}}>
      {rings.map(lv=><polygon key={lv} points={axes.map(i=>(CX+(ox(i)-CX)*lv)+","+(CY+(oy(i)-CY)*lv)).join(" ")} fill="none" stroke="rgba(255,255,255,0.07)" strokeWidth="1"/>)}
      {axes.map(i=><line key={i} x1={CX} y1={CY} x2={ox(i)} y2={oy(i)} stroke="rgba(255,255,255,0.07)" strokeWidth="1"/>)}
      <polygon points={dataStr} fill={C.mint+"2A"} stroke={C.mint} strokeWidth="2" strokeLinejoin="round"/>
      {sm.map((m,i)=><circle key={i} cx={vx(m,i)} cy={vy(m,i)} r="4" fill={m.color} stroke="rgba(0,0,0,0.5)" strokeWidth="1"/>)}
      {sm.map((m,i)=>{
        const lx=CX+LD*Math.cos(ang(i));
        const ly=CY+LD*Math.sin(ang(i));
        const anchor=lx<CX-4?"start":lx>CX+4?"end":"middle";
        return(<g key={i}>
          <text x={lx} y={ly-4} textAnchor={anchor} dominantBaseline="middle" fontSize="10" fontWeight="700" fill={m.color}>{m.g}</text>
          <text x={lx} y={ly+9} textAnchor={anchor} dominantBaseline="middle" fontSize="9" fill={m.color+"CC"}>{m.pct===100?"✓":m.pct+"%"}</text>
        </g>);
      })}
      {[25,50,75].map(v=><text key={v} x={CX+3} y={CY-R*(v/100)+4} fontSize="7" fill="rgba(255,255,255,0.18)" textAnchor="start">{v}%</text>)}
    </svg>
  );
}

// ─── MUSCLE DETAIL SCREEN ────────────────────────────────────
function MuscleDetailScreen({muscles,onBack,onNavigate}){
  const[period,setPeriod]=useState("Semana");
  const periods=["Semana","Mês","Trim.","Ano"];

  // Build per-period muscle volume data
  const now=new Date();
  const periodDays={"Semana":7,"Mês":30,"Trim.":91,"Ano":365};
  const days=periodDays[period]||7;
  const cutoff=new Date(now.getTime()-days*86400000).toISOString().slice(0,10);
  const sessions=getAllSessions().filter(s=>s.date>=cutoff);

  const muscleGroups=["Peito","Costas","Pernas","Ombros","Braços","Core","Glúteos","Panturrilha"];
  const EX_MAP={
    "Peito":["Supino","Crucifixo","Peitoral","Inclinado","Declinado"],
    "Costas":["Terra","Remada","Puxada","Barra Fixa","Pull"],
    "Pernas":["Agachamento","Leg Press","Cadeira","Mesa Flexora","Afundo"],
    "Ombros":["Desenvolvimento","Elevação Lateral","Aberturas","Arnold","Ombro"],
    "Braços":["Rosca","Tríceps","Coice","Martelo","Scott","Concentrada","Extensão"],
    "Core":["Abdominal","Core","Prancha","Elevação De Pernas"],
    "Glúteos":["Agachamento","Afundo","Romeno","Leg Press","Hip Thrust","Glúteo"],
    "Panturrilha":["Panturrilha","Elevação de Panturrilha","Calf"],
  };

  const muscleVol=muscleGroups.reduce((acc,g)=>{
    const vol=sessions.reduce((sum,s)=>sum+(s.exercises||[]).filter(e=>EX_MAP[g]?.some(kw=>(e.name||"").toLowerCase().includes(kw.toLowerCase()))).reduce((a,e)=>a+(e.vol||0),0),0);
    const sets=sessions.reduce((sum,s)=>sum+(s.exercises||[]).filter(e=>EX_MAP[g]?.some(kw=>(e.name||"").toLowerCase().includes(kw.toLowerCase()))).reduce((a,e)=>a+(e.sets||0),0),0);
    acc[g]={vol:Math.round(vol/100)/10,sets};
    return acc;
  },{});

  const maxVol=Math.max(...Object.values(muscleVol).map(v=>v.vol),1);

  return(
    <div style={{background:"#080A0E",minHeight:"100dvh",padding:"52px 20px 120px"}}>
      <div style={{display:"flex",alignItems:"center",gap:12,marginBottom:20}}>
        <button onClick={onBack} style={{width:36,height:36,borderRadius:"50%",background:"rgba(255,255,255,0.06)",border:"1px solid rgba(255,255,255,0.1)",color:C.text,fontSize:18,cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center"}}>‹</button>
        <div style={{fontSize:18,fontWeight:800,color:C.text}}>Distribuição Muscular</div>
      </div>

      {/* Period tabs */}
      <div style={{display:"flex",background:C.card,borderRadius:12,padding:3,marginBottom:16,border:"1px solid "+C.border}}>
        {periods.map(p=>(
          <button key={p} onClick={()=>setPeriod(p)} style={{flex:1,padding:"8px 4px",borderRadius:9,border:"none",cursor:"pointer",fontSize:11,fontWeight:700,background:period===p?"rgba(255,255,255,0.12)":"transparent",color:period===p?C.text:C.muted}}>{p}</button>
        ))}
      </div>

      {/* Stats row */}
      <div style={{display:"grid",gridTemplateColumns:"1fr 1fr 1fr",gap:8,marginBottom:14}}>
        {[{l:"Prontos",v:muscles.filter(m=>m.pct===100).length,c:C.mint},{l:"Recuperando",v:muscles.filter(m=>m.pct<100&&m.pct>=50).length,c:C.amber},{l:"Fadigados",v:muscles.filter(m=>m.pct<50).length,c:C.coral}].map(s=>(
          <div key={s.l} style={{background:C.card,border:"1px solid "+C.border,borderRadius:14,padding:"12px 4px",textAlign:"center"}}>
            <div style={{fontSize:24,fontWeight:900,color:s.c}}>{s.v}</div>
            <div style={{fontSize:10,color:C.sub,marginTop:2}}>{s.l}</div>
          </div>
        ))}
      </div>

      {/* Spider chart */}
      <div style={{background:C.card,border:"1px solid "+C.border,borderRadius:20,padding:"16px",marginBottom:14}}>
        <div style={{fontSize:12,fontWeight:700,color:C.sub,textTransform:"uppercase",letterSpacing:"0.08em",marginBottom:8}}>Recuperação muscular</div>
        <SpiderChart muscles={muscles} size={300}/>
      </div>

      {/* Volume by muscle */}
      <div style={{background:C.card,border:"1px solid "+C.border,borderRadius:20,padding:"16px",marginBottom:14}}>
        <div style={{fontSize:12,fontWeight:700,color:C.sub,textTransform:"uppercase",letterSpacing:"0.08em",marginBottom:12}}>Volume por grupo · {period}</div>
        {muscleGroups.map(g=>{
          const mv=muscleVol[g]||{vol:0,sets:0};
          const muscle=muscles.find(m=>m.g===g)||{pct:0,color:C.muted};
          const barPct=maxVol>0?mv.vol/maxVol:0;
          return(
            <div key={g} style={{marginBottom:12}}>
              <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:4}}>
                <span style={{fontSize:11,fontWeight:700,color:muscle.color}}>{g}</span>
                <div style={{display:"flex",gap:12,alignItems:"center"}}>
                  <span style={{fontSize:10,color:C.muted}}>{mv.sets} séries</span>
                  <span style={{fontSize:11,fontWeight:700,color:C.text}}>{mv.vol}t</span>
                </div>
              </div>
              <div style={{height:6,background:C.card,borderRadius:3,overflow:"hidden"}}>
                <div style={{height:"100%",width:(barPct*100)+"%",background:muscle.color,borderRadius:3,transition:"width 0.5s"}}/>
              </div>
            </div>
          );
        })}
      </div>

      {/* Recovery times */}
      <div style={{background:C.card,border:"1px solid "+C.border,borderRadius:20,padding:"16px"}}>
        <div style={{fontSize:12,fontWeight:700,color:C.sub,textTransform:"uppercase",letterSpacing:"0.08em",marginBottom:12}}>Estado de recuperação</div>
        {muscles.map(m=>(
          <div key={m.g} style={{display:"flex",alignItems:"center",gap:10,marginBottom:10}}>
            <div style={{fontSize:11,color:C.sub,width:58,flexShrink:0}}>{m.g}</div>
            <div style={{flex:1,height:6,background:C.card,borderRadius:3,overflow:"hidden"}}>
              <div style={{height:"100%",width:m.pct+"%",background:m.color,borderRadius:3}}/>
            </div>
            <div style={{fontSize:11,fontWeight:700,color:m.color,width:34,textAlign:"right"}}>{m.pct===100?"✓":m.pct+"%"}</div>
            {m.lastDays!=null&&<div style={{fontSize:9,color:C.muted,width:36,textAlign:"right"}}>há {m.lastDays}d</div>}
          </div>
        ))}
        <div style={{marginTop:10,paddingTop:10,borderTop:"1px solid "+C.border,fontSize:9,color:C.muted,lineHeight:1.7}}>
          Core 36h · Ombros/Braços 48h · Peito 60h · Costas 72h · Pernas 96h
        </div>
      </div>
      <BottomNav active="corpo" onNavigate={onNavigate}/>
    </div>
  );
}

